INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9130, 'koKR', 'Towary ze Srebrnej Luny', 'Witaj, $gochotniku:ochotniczko;! Kończą nam się tu zapasy, ale krwawe elfy obiecały nam wsparcie materiałowe. I tu właśnie wkraczasz ty.$B$BZanieś ten list przewozowy mistrzowi lotów Słonecznemu Skrzydłu. Wyjaśni ci, jak najlepiej dostać się do Srebrnej Luny.', 'Dostarcz list przewozowy kwatermistrzyni Lymel mistrzowi lotów Słonecznemu Skrzydłu w Trankwillienie.', '', '', '', '', '', '', 0),
(9138, 'koKR', 'Wioska Słonecznej Korony', 'Jesteśmy tu otoczeni, $N. Plaga opanowała wszystkie okoliczne wioski!$B$BMusisz natychmiast wyruszyć na północny wschód, do Wioski Słonecznej Korony, i rozprawić się z nerubiańskimi sługami Plagi. Nie przeoczysz ich – to stwory podobne do pająków.$B$BNie ma czasu do stracenia... Quel\'Thalas musi zostać odzyskane!', 'Zabij 10 strażników Nerubis, a następnie wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9139, 'koKR', 'Wioska Złotej Mgły', 'Odnieśliśmy jeden sukces, ale musimy odzyskać jeszcze dwie wioski!$B$BNaszym następnym celem jest Wioska Złotej Mgły. Leży na północnym zachodzie i opanowały ją duchy wysokich elfów, które niegdyś w niej mieszkały. Makabryczne, wiem, ale najwyraźniej właśnie po takie metody lubi sięgać Plaga.$B$BIdź i pokonaj te duchy i upiory, $N. Dotrzesz tam zachodnią drogą z Trankwillienu.', 'Pokonaj 6 duchów quel\'dorei i 4 upiory quel\'dorei w Wiosce Złotej Mgły, a następnie wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9140, 'koKR', 'Wioska Bieżywiatrów', '$N, nadchodzi ostatnia bitwa o wioski Widmowych Ziem. Wioskę Bieżywiatrów na południowym zachodzie opanowały liczne siły potężniejszych oddziałów uderzeniowych Plagi: cienie i gargulce. Będziesz grotem naszej ofensywy – przetrzebisz ich szeregi.$B$BMagistrowie z pobliskiego Sanktuarium Słońca mają tym razem szczególną prośbę: chcą zbadać szczątki tych sług Plagi w nadziei, że znajdą pomysłowe sposoby walki z nimi.$B$BUdanych łowów!', 'Zbierz 6 porcji widmowej substancji i 4 odłamki gargulca. Zanieś je arkaniście Vandrilowi w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9143, 'koKR', 'Rozprawa z Zeb\'Sora', 'Porucznik zamiast najpierw rozpoznać sytuację, pognał nas do walki z trollami po drugiej stronie jeziora. Jego głupota zdziesiątkowała nasz oddział! Słyszysz mnie, Tomathrenie? Jesteś idiotą!$B$BPomożesz nam, $N? Z tymi trollami wciąż trzeba się rozprawić. Ja muszę tu zostać i niańczyć porucznika – chyba postradał zmysły.$B$BIdź na wschód, na drugi brzeg jeziora, do Zeb\'Sora. Chcę zemsty... przynieś mi ich uszy, zrobię sobie z nich śliczny naszyjnik!', 'Zbierz 6 uszu trolli z Zeb\'Sora i zanieś je tropicielce Valannie na Widmowych Ziemiach.', '', 'Wróć do tropicielki Valanny na Widmowych Ziemiach.', '', '', '', '', 0),
(9145, 'koKR', 'Pomóż tropicielce Valannie!', '$N, nie mogę tu siedzieć i czekać na audiencję u najwyższego egzekutora czy Damy Złotonośnej! To nie może czekać!$B$BRozprawialiśmy się z trollami Cienistej Sosny z Zeb\'Sora, na północnym wschodzie, po drugiej stronie Jeziora Elrendar. Ale porucznik spartaczył atak i straciliśmy wielu Obieżyświatów. A potem zupełnie się rozsypał. Tropicielka Valanna wysłała mnie tutaj, a tropicielkę Salissę do Enklawy Obieżyświatów po pomoc.$B$BProszę, odnajdź ich, $N. Valanna jest ciężko ranna, a z porucznika nie ma żadnego pożytku.', 'Odnajdź tropicielkę Valannę i porucznika Tomathrena na brzegu Jeziora Elrendar na Widmowych Ziemiach, w pobliżu Wioski Słonecznej Korony.', '', '', '', '', '', '', 0),
(9146, 'koKR', 'Zgłoś się do kapitana Heliosa', 'Mam do ciebie ostatnią prośbę, $N. Na wypadek gdyby tropicielka Salissa nie dotarła do Enklawy Obieżyświatów na południowym brzegu jeziora, musisz tam pójść i sprowadzić pomoc.$B$BZgłoś się do kapitana Heliosa i powiedz mu, co się tu stało. Na pewno przyśle pomoc najszybciej, jak zdoła.', 'Porozmawiaj z kapitanem Heliosem w Enklawie Obieżyświatów na południowym brzegu Jeziora Elrendar na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9149, 'koKR', 'Zarażone wybrzeże', 'Aby znaleźć lekarstwo na zarazę, musimy zrozumieć, jak działa ona na różne stworzenia – od najbardziej złożonych form życia po najpodlejsze podgatunki.$B$BPrzybyłem tu, by badać murloki, bo – podobnie jak my – zachowały wolną wolę po śmierci. Co czyni te nędzne kundle tak wyjątkowymi? Muszę się tego dowiedzieć, $N!$B$BUdaj się na północny zachód i przynieś mi ich kręgosłupy, abym mógł zbadać, jak zaraza gromadzi się w ich szpiku. Kto wie, jakie sekrety kryją ich kosteczki?', 'Przynieś 6 zarażonych kręgosłupów murloków aptekarzowi Renzithenowi w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do aptekarza Renzithena w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9150, 'koKR', 'Ratowanie przeszłości', 'Wyobrażasz sobie? Na południowy wschód stąd działa prawdziwe, sprawne tajemne sanktuarium – Sanktuarium Słońca. Zjechali się tam najrozmaitsi ważni magistrowie, by wspólnie nim kierować.$B$BRzecz jasna wszyscy zapomnieli o Sanktuarium Księżyca. Niewiele z niego zostało, a jego energie zrodziły dziwaczne stworzenia.$B$BJa jednak nie zwykłem marnować cennych zasobów. Udaj się do Sanktuarium Księżyca i spróbuj odzyskać skrystalizowane esencje z tamtejszych stworzeń.', 'Magister Darenis chce, żebyś $gudał:udała; się do Sanktuarium Księżyca na zachód od Trankwillienu i $godzyskał:odzyskała; 8 skrystalizowanych esencji many z tajemnych pożeraczy i zmienników many, które zamieszkują budowlę.', '', 'Wróć do magistra Darenisa w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9151, 'koKR', 'Sanktuarium Słońca', '$GDowiodłeś:Dowiodłaś; swojej lojalności wobec Trankwillienu i $gpomogłeś:pomogłaś; nam bronić go przed Plagą. Kilku z naszych najpotężniejszych magistrów przybyło ze Srebrnej Luny, by pomóc nam zanieść walkę pod sam próg wroga.$B$BOdbudowali tajemne sanktuarium na południu i wyparli Plagę z okolicy. Planują rozpocząć ofensywę na Ostoję Śmierci, twierdzę Dar\'Khana. Dobrze zrobisz, jeśli do nich dołączysz, $N. Z pewnością przyda im się ktoś tak $gdoświadczony:doświadczona; jak ty.', 'Porozmawiaj z magistrem Idonisem w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9152, 'koKR', 'Zapasy Tombera', 'Jak mam zaopatrywać wojsko, skoro nie mogę nawet bezpiecznie sprowadzić tu swoich towarów? Obiecano mi eskortę, która nigdy się nie zjawiła. A potem, gdy napadła mnie banda ghuli, musiałem porzucić jeden z wozów na zachodzie!$B$BChcesz pomóc, a przy okazji pozwolić mi otworzyć interes? Idź zachodnią drogą z miasta i miń cmentarz. Po drugiej stronie Trupiej Blizny droga się rozwidla. Wzgórze, na którym musiałem zostawić wóz, leży tuż za rozwidleniem.', 'Odzyskaj zapasy Rathisa Tombera i zanieś mu je do Trankwillienu na Widmowych Ziemiach.', '', 'Wróć do Rathisa Tombera w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9155, 'koKR', 'Wzdłuż Trupiej Blizny', 'Skoro $gdotarłeś:dotarłaś; aż tutaj, zapewne wiesz o Trupiej Bliźnie i o tym, że bezmyślne sługi Plagi po dziś dzień podążają szlakiem zniszczenia, który Arthas wyrąbał w drodze do Srebrnej Luny.$B$BNa coś się przydaj i przetrzeb szeregi Plagi na Bliźnie. Jeśli okażesz się coś $gwart:warta;, szepnę za tobą dobre słowo.', 'Zabij 10 powstałych głodomorów i 10 wychudłych kanibali na Trupiej Bliźnie. Po nagrodę wróć do tropiciela śmierci Rathiela w Trankwillienie.', '', 'Wróć do tropiciela śmierci Rathiela w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9156, 'koKR', 'Poszukiwani: Zgniłokłykieć i Luzran', 'Niniejszym wyznacza się nagrodę za plugastwa zwane Zgniłokłykciem i Luzranem. Te straszliwe twory Dar\'Khana są niezwykle groźne; widziano je, jak patrolują okolice Wyjącego i Krwawiącego Ziggurata. Chętni do odebrania nagrody muszą na dowód czynu przedstawić głowy plugastw tropicielowi śmierci Rathielowi.', 'Odszukaj na Widmowych Ziemiach Zgniłokłykcia i Luzrana. Po nagrodę przynieś ich głowy tropicielowi śmierci Rathielowi w Trankwillienie.', '', 'Wróć do tropiciela śmierci Rathiela w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9157, 'koKR', 'Zapomniane rytuały', 'Co roku my, mieszkańcy Wioski Słonecznej Korony, odprawialiśmy rytuał, który miał utrzymać pod naszą kontrolą różne oblicza natury. Władzę nad żywiołem wody symbolizowało przyzwanie i zniewolenie żywiołaka imieniem Aquantion. Dzięki nikczemnemu wypaczeniu naszej magii łotr zerwał więzy i to on zniewolił nas!$B$BPodczas rytuału nosiliśmy medaliony w kształcie fal. Poszukaj ich na dnie jeziora – będą nam potrzebne, by uwolnić duchy moich rodaków!', 'Przynieś 8 medalionów czoła fali Geranisowi Białemu Porankowi na Widmowych Ziemiach.', '', 'Wróć do Geranisa Białego Poranka na Widmowych Ziemiach.', '', '', '', '', 0),
(9158, 'koKR', 'Nosiciele zarazy', 'Przybywając na Widmowe Ziemie, wykazujesz się odwagą, $N. Czeka tu mnóstwo pracy, a brakuje dzielnych dusz, które by się jej podjęły.$B$BMam dla ciebie niewdzięczne zadanie, jeśli zechcesz wesprzeć naszą sprawę. Zaraza skaziła nawet tutejsze dzikie zwierzęta i musimy powstrzymać jej rozprzestrzenianie. Poluj na rysie widmoszpony na wschód i południe stąd i wróć, gdy zabijesz ich dostatecznie wiele.', 'Obieżyświatka Sedina z Enklawy Obieżyświatów na Widmowych Ziemiach chce, żebyś $gzabił:zabiła; 10 rysi widmoszponów.', '', 'Wróć do Obieżyświatki Sediny w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9159, 'koKR', 'Powstrzymanie zarazy', '$GDowiodłeś:Dowiodłaś;, że jesteś $gwartościowym sojusznikiem:wartościową sojuszniczką;, $N. Kontynuuj swoje zadanie i wytrop więcej zarażonych zwierząt. Tym razem odszukaj groźniejsze bestie. Poluj na wrzecionowe czyhacze na zachód od Trupiej Blizny i na wampiryczne mgliste nietoperze tuż na południe stąd. Gdy skończysz, wróć do mnie.', 'Obieżyświatka Sedina z Enklawy Obieżyświatów na Widmowych Ziemiach chce, żebyś $gzabił:zabiła; 8 wrzecionowych czyhaczy i 10 wampirycznych mglistych nietoperzy.', '', 'Wróć do Obieżyświatki Sediny w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9160, 'koKR', 'Zbadaj An\'daroth', '$N, mamy kłopot z grupą nocnych elfów, które niedawno zajęły pobliską wyspę. Rozbiły niewielki obóz przy starym węźle linii mocy wysokich elfów, An\'daroth, na północnym zachodzie. Prowadzi tam polna ścieżka, zaraz za Trupią Blizną.$B$BProponuję, byś $gużyczył:użyczyła; nam swej pomocy: udaj się tam, zbadaj, co knują, i zabij tylu zarozumiałych nocnych elfów, ilu zdołasz.', 'Zbadaj okolice An\'daroth, zabij 12 szpiegów Strażniczek, a następnie wróć do Damy Złotonośnej w Trankwillienie na Widmowych Ziemiach.', 'Zbadaj An\'daroth', 'Wróć do Damy Złotonośnej na Widmowych Ziemiach.', '', '', '', '', 0),
(9161, 'koKR', 'Cień zdrajcy', 'Uważa się, że Dar\'Khan Drathir powrócił zza grobu, by władać armiami Plagi na Widmowych Ziemiach. Dar\'Khan dawno temu sprzymierzył się z Plagą... a przecież niegdyś był żywym, oddychającym elfem. Wiele czasu spędzał w Iglicy Gwiazdy Zarannej, na północny wschód stąd. Ukrywał się tam przez wiele nocy, knując przeciw własnemu ludowi.$B$BPrzeszukaj wieżę w poszukiwaniu informacji, $N. Może prowadził dziennik albo robił notatki. Nigdy nie wiadomo, gdzie trafi się coś przydatnego.', 'Udaj się do Iglicy Gwiazdy Zarannej na Widmowych Ziemiach i poszukaj wszelkich śladów przeszłości Dar\'Khana.', '', '', '', '', '', '', 0),
(9162, 'koKR', 'Ślady przeszłości', 'Gdy przeglądasz stronice dziennika, ogarnia cię niepokojące poczucie, że ktoś cię obserwuje.$B$BTreść budzi grozę. Dusza Dar\'Khana była przepełniona nienawiścią i pogardą dla własnego ludu. Wszystkie jego knowania i spiski opisano tu z najdrobniejszymi szczegółami.$B$BByć może znajdzie się tu coś, co przyda się Vynnie.', 'Wróć z dziennikiem Dar\'Khana do tropicielki Vynny w Enklawie Obieżyświatów.', '', '', '', '', '', '', 0),
(9163, 'koKR', 'Na okupowane terytorium', 'A teraz bardziej bezpośredni sposób, by ustalić, co naprawdę knują te nocne elfy: udasz się na ich wyspę i wykradniesz wszelkie informacje, jakie zdołasz zdobyć.$B$BIdź drogą na zachód z miasta, na Wyspę Shalandis tuż u wybrzeża. Odzyskaj wszelkie plany, jakie mogą mieć na wyspie lub na swoim statku.', 'Wykradnij plany nocnych elfów: An\'daroth, plany nocnych elfów: An\'owyn i plany nocnych elfów: podglądanie sin\'dorei, a następnie zanieś je Damie Złotonośnej w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do Damy Złotonośnej w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9164, 'koKR', 'Jeńcy w Ostoi Śmierci', 'Ach, tak. Jedno z moich najwspanialszych dzieł. Ten wywar przełamie większość postaci alchemicznie wywołanego odrętwienia.$B$BSkutki uboczne to dezorientacja, mdłości i – w rzadkich przypadkach – przejściowa ślepota. Wszystko to i tak jest o wiele lepsze od tego, co Plaga zamierza zrobić z więźniami w Ostoi Śmierci, jeśli chcesz znać moje zdanie.$B$BPowodzenia, $gdzielny:dzielna; $N. Będzie ci potrzebne.', 'Zanieś wzmacniający wywar Renzithena do Ostoi Śmierci i uratuj ucznia Varnisa, aptekarkę Enith i tropiciela Vedorana. Po nagrodę wróć do arkanistki Janedy w Sanktuarium Słońca.', '', 'Wróć do arkanistki Janedy w Sanktuarium Słońca na Widmowych Ziemiach.', 'Aptekarka Enith uratowana', 'Uczeń Varnis uratowany', '', 'Tropiciel Vedoran uratowany', 0),
(9166, 'koKR', 'Dostarcz plany do An\'telas', 'Musisz dostarczyć w moim imieniu odzyskane plany nocnych elfów do An\'telas. To na wschodzie, na południowych stokach Szczytu Słonecznego Pastwiska, tuż na północny wschód od Sanktuarium Słońca.$B$BPrzebywa tam magister Sylastor, który prowadzi badania nad energią węzła linii mocy, by wykorzystać ją w walce z Plagą. Niech przejrzy te plany i rzuci nieco światła na to, co knują nocne elfy.', 'Dostarcz plany nocnych elfów magistrowi Sylastorowi w An\'telas na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9167, 'koKR', 'Zguba zdrajcy', 'Wszystko, co czyniliśmy na Widmowych Ziemiach, czyniliśmy po to, by odzyskać to, co słusznie nasze. Plaga zbyt długo trzymała ten region w żelaznym uścisku.$B$BNadszedł czas odpłaty, $N. Dzięki twojej pomocy i pomocy naszych nowych sojuszników, Porzuconych, wkrótce dokonamy zemsty.$B$BTen, który chciał wykraść moc Słonecznej Studni, musi zginąć. Udaj się do Ostoi Śmierci, twierdzy Plagi na południe od Trupiej Blizny. Przynieś mi głowę Dar\'Khana, a twoje czyny przejdą do historii!', 'Zabij Dar\'Khana Drathira w Ostoi Śmierci i przynieś jego głowę magistrowi Kaendrisowi w Sanktuarium Słońca na Widmowych Ziemiach.', '', 'Wróć do magistra Kaendrisa w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', 0),
(9168, 'koKR', 'Serce Ostoi Śmierci', 'W głębi Ostoi Śmierci nasi wrogowie usiłują stworzyć silniejszych, groźniejszych widmowych żołnierzy. Te odrażające stwory to doskonałe machiny do zabijania, własnoręcznie wykonane przez samego Dar\'Khana i zahartowane mroczną magią Ostoi Śmierci.$B$BUdaj się do Wieży Potępionych w Ostoi Śmierci i zniszcz je, $N. Nie możemy pozwolić, by armia wroga rosła w siłę, podczas gdy my z trudem utrzymujemy przyczółek na Widmowych Ziemiach.', 'Zniszcz 8 oczu Dar\'Khana i złóż raport magistrowi Idonisowi w Sanktuarium Słońca na Widmowych Ziemiach.', '', 'Wróć do magistra Idonisa na Widmowych Ziemiach.', '', '', '', '', 0),
(9169, 'koKR', 'Wyłącz An\'owyn', 'Ich księżycowe kryształy służą do wieszczenia – zamierzają nas szpiegować! Wiem, że An\'daroth nie da im dość mocy, ale An\'owyn, prosto na południe stąd, z pewnością tak!$B$BZ planów poznałem podstawy działania tych księżycowych kryształów – dość, by je wyłączyć. Są sprzężone z kluczem, dzięki któremu można je wygasić. Musisz udać się do An\'owyn, odebrać jednemu z nocnych elfów kulę kontrolną i użyć jej na księżycowym krysztale, by pokrzyżować im plany!$B$BPośpiesz się, $N!', 'Zdobądź kulę kontroli kryształów i użyj jej, by wyłączyć księżycowy kryształ nocnych elfów w An\'owyn. Następnie wróć do magistra Sylastora w An\'telas na Widmowych Ziemiach.', '', 'Wróć do magistra Sylastora na Widmowych Ziemiach.', 'Księżycowy kryształ nocnych elfów wyłączony', '', '', '', 0),
(9170, 'koKR', 'Porucznicy Dar\'Khana', 'Plugawy zdrajca Dar\'Khan zdobył wielką władzę w szeregach Plagi. Jego porucznicy dowodzą ogromnymi armiami nieumarłych, które rzucają przeciw naszym topniejącym siłom.$B$BMasophet Czarny, Jurion Zwodziciel, Borgoth Upuszczacz Krwi, Mirdoran Upadły. Zapamiętaj dobrze te imiona, bo na Widmowych Ziemiach ci przywódcy Plagi ustępują tylko samemu Dar\'Khanowi. Zabij ich, a ich bezmyślne armie pogrążą się w chaosie.', 'Magister Idonis chce, żebyś $gzapuścił:zapuściła; się do Ostoi Śmierci i $gzabił:zabiła; Masopheta Czarnego, Juriona Zwodziciela, Borgotha Upuszczacza Krwi i Mirdorana Upadłego. Po wykonaniu zadania złóż mu raport w Sanktuarium Słońca na Widmowych Ziemiach.', '', 'Wróć do magistra Idonisa w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', 0),
(9171, 'koKR', 'Kulinarna chrupkość', 'To nie do zniesienia! Nie mam tu z czego gotować! Milady wzywa mnie ze Srebrnej Luny; należy jej się kuchnia godna jej pozycji. Czyż nie? A tymczasem przybywam tutaj i nie ma jedzenia. Musisz wyruszyć, $N, i przynieść świeżą zwierzynę, abym miał z czego przyrządzić posiłek.$B$BDama Złotonośna woli, gdy jej jedzenie chrupie. Na południowym zachodzie, po drugiej stronie Trupiej Blizny, pełno jest wrzecionowych czyhaczy. Obrzydliwe, wiem, ale z tym właśnie przychodzi nam pracować.', 'Zbierz 5 chrupkich pajęczych odnóży i zanieś je mistrzowi kuchni Mouldierowi w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do mistrza kuchni Mouldiera w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9172, 'koKR', 'Zgłoś się do magistra Kaendrisa', 'Magistrowie z Sanktuarium Słońca z pomocą Porzuconych poczynili wielkie postępy w badaniu słabości Plagi. Magister Kaendris będzie wiedział, co zrobić z tymi informacjami.$B$BSanktuarium Słońca znajdziesz na południowy zachód stąd. Musisz się pośpieszyć, $N. Dar\'Khan to przebiegły wróg i śledzi każdy nasz ruch!', 'Zanieś dziennik Dar\'Khana magistrowi Kaendrisowi w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9173, 'koKR', 'Odbicie Iglicy Bieżywiatrów', '$N, chcę, żebyś $godbił:odbiła; Iglicę Bieżywiatrów!$B$BTo doprawdy zaszczyt. Iglica Bieżywiatrów to rodzinny dom Lady Sylwany Bieżywiatr, królowej Porzuconych i niegdysiejszej generał tropicieli elfów. Teraz jednak opanowała ją bezmyślna Plaga.$B$BBy się tam dostać, idź drogą na południe aż do rozwidlenia. Skręć w prawo, a po przejściu przez Trupią Bliznę idź dalej na południowy zachód. Nie przeoczysz jej.', 'Zabij 8 akolitów z Ostoi Śmierci i 10 upadłych tropicieli, a następnie wróć do najwyższego egzekutora Mavrena w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do najwyższego egzekutora Mavrena w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9174, 'koKR', 'Pokonanie Aquantiona', 'Tego feralnego dnia, gdy ten krnąbrny żywiołak zbuntował się przeciw nam, zakończył wiele żywotów. Wezwał nędzne murloki, by zakłóciły nasze obrzędy, wypaczył naszą magię i obrócił ją przeciw nam.$B$BPokaż mu, że nasze pragnienie zemsty nie osłabło! Weź te medaliony i złóż je na Ołtarzu mistrzostwa przypływu na dnie jeziora. Aquantion natychmiast odpowie na twoje wezwanie!$B$BStrzeż się, $N! Bez naszej magii, która go spętała, jego gniew nie będzie znał granic. Zniszcz Aquantiona, abyśmy mogli zaznać spoczynku!', 'Geranis Biały Poranek chce, żebyś $gpopłynął:popłynęła; na dno jeziora na wschód od Wioski Słonecznej Korony i $gużył:użyła; pęku medalionów na Ołtarzu mistrzostwa przypływu. Przyzwij i zabij żywiołaka zwanego Aquantionem, a następnie wróć do Geranisa.', '', 'Wróć do Geranisa Białego Poranka na Widmowych Ziemiach.', '', '', '', '', 0),
(9175, 'koKR', 'Naszyjnik Pani', 'Naszyjnik lśni – to niezwykły klejnot, który zdaje się nie poddawać mrokowi przenikającemu Widmowe Ziemie. Sądząc po inskrypcji i miejscu, w którym go $gznalazłeś:znalazłaś;, musi to być zaginiona własność samej Lady Sylwany Bieżywiatr!$B$BMoże najlepiej będzie najpierw zanieść go najwyższemu egzekutorowi Mavrenowi w Trankwillienie? Wygląda na to, że to najwyższy rangą Porzucony w okolicy – z pewnością będzie wiedział, co z nim zrobić.', 'Zanieś Naszyjnik Pani najwyższemu egzekutorowi Mavrenowi w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9176, 'koKR', 'Bliźniacze zigguraty', 'Według tego dziennika Dar\'Khan obiecał Pladze dwa potężne elfie artefakty: kamień światła i kamień płomienia. Nasycono je magiczną energią Słonecznej Studni i dostrojono tak, by chroniły przed Plagą.$B$BKryształy miały zostać przeniesione tam, gdzie dziś wznoszą się Wyjący Ziggurat i Krwawiący Ziggurat, pośrodku Trupiej Blizny. Jeśli wciąż tam są, musimy je odzyskać. Ich moc bardzo się nam przyda w walce z wrogiem.', 'Udaj się do Krwawiącego Ziggurata i Wyjącego Ziggurata i odzyskaj kamień światła oraz kamień płomienia. Gdy je odzyskasz, wróć do magistra Kaendrisa w Sanktuarium Słońca.', '', 'Wróć do magistra Kaendrisa w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', 0),
(9192, 'koKR', 'Kłopoty w Kopalniach Podziemnego Światła', 'Kopalnie Podziemnego Światła na południowym zachodzie opanował klan gnoli, które nazywają siebie Czarnołapymi. Nie muszę ci chyba przypominać, jak ważne są dla nas te kopalnie jako strategiczny zasób w toczącej się tu, na Widmowych Ziemiach, kampanii!$B$BIdź drogą na południe z miasta i na rozwidleniu skręć w prawo. Tuż za zigguratem po prawej stronie zobaczysz krótką polną ścieżkę na zachód. Podążaj nią.$B$BRuda musi płynąć!', 'Zabij 8 gnoli Czarnołapych, 6 padlinożerców Czarnołapych i 4 szamanów Czarnołapych, a następnie wróć do tropiciela śmierci Maltendisa w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do tropiciela śmierci Maltendisa w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9193, 'koKR', 'Zbadaj Katakumby Amanów', '$N, nasze źródła donoszą, że trolle pochowane w Katakumbach Amanów wewnątrz Szczytu Słonecznego Pastwiska powstają z martwych. Dama Złotonośna życzy sobie, byś $gzbadał:zbadała; te katakumby i $gpodpalił:podpaliła; wszelkie nieożywione szczątki, na jakie się natkniesz, aby zapobiec powstawaniu kolejnych takich stworów.$B$BNajszybciej dotrzesz tam, idąc drogą na północ z miasta i skręcając w prawo na pierwszym rozwidleniu. Znajdziesz się wtedy po północnej stronie szczytu, więc wejścia szukaj od południa.', 'Zbadaj Katakumby Amanów i spal 10 zmumifikowanych szczątków trolli, a następnie wróć do doradczyni Valwyn w Trankwillienie na Widmowych Ziemiach.', 'Zbadaj Katakumby Amanów', 'Wróć do doradczyni Valwyn w Trankwillienie na Widmowych Ziemiach.', 'Zmumifikowane szczątki trolli spalone', '', '', '', 0),
(9199, 'koKR', 'Trollowe juju', 'Zwłoki trolli pochowanych w Katakumbach Amanów powstają z martwych! Chcę, żebyś $gposzedł:poszła; tam i $gprzyniósł:przyniosła; dowód ich ostatecznego końca. Niektóre z tych trollich mumii, a także ich żywi pobratymcy, noszą juju – świecące przedmioty, w których kryje się nieznane źródło mocy. Pewnie to ono je ożywia!$B$BKatakumby leżą we wnętrzu Szczytu Słonecznego Pastwiska, prosto na wschód stąd. Słyszałem, że najłatwiej dostać się do środka od północnej ściany góry. Zajmij się tym, $N!', 'Zbierz 8 trollowych juju i zanieś je tropicielowi śmierci Maltendisowi w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do tropiciela śmierci Maltendisa na Widmowych Ziemiach.', '', '', '', '', 0),
(9207, 'koKR', 'Próbki rudy Podziemnego Światła', 'Przysłano mnie tu z Sanktuarium Słońca po próbki rudy, ale gnole opanowały to miejsce! Jeśli szybko nie dostarczę tych próbek magistrowi, podadzą moją głowę na tacy. Może ty mi pomożesz, $N?$B$BRudę znajdziesz w tutejszych żyłach cyny i miedzi, a gnole też ją przy sobie noszą. Gdy zbierzesz dość, zanieś ją magistrowi Quallestisowi do Sanktuarium Słońca, prosto na wschód stąd. Przejdź przez Trupią Bliznę, a znajdziesz sanktuarium tuż na południe od Szczytu Słonecznego Pastwiska.', 'Zbierz 6 bryłek rudy Podziemnego Światła i dostarcz je magistrowi Quallestisowi w Sanktuarium Słońca na Widmowych Ziemiach.', '', 'Wróć do magistra Quallestisa w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', 0),
(9212, 'koKR', 'Ucieczka z katakumb', 'Te trolle wciągnęły mnie w zasadzkę i trzymają w tej klatce. Chyba chcą złożyć mnie w ofierze! Pomóż mi się stąd wydostać!$B$BZamek klatki nie jest zbyt skomplikowany... po prostu nie sięgam do niego z tej strony. Proszę, odprowadź mnie z powrotem do Enklawy Obieżyświatów. Kapitan Helios na pewno cię nagrodzi, a ja będę ci dozgonnie wdzięczna!', 'Odprowadź tropicielkę Lilathę do kapitana Heliosa w Enklawie Obieżyświatów na Widmowych Ziemiach.', 'Odprowadź tropicielkę Lilathę z powrotem do Enklawy Obieżyświatów', 'Wróć do kapitana Heliosa w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9214, 'koKR', 'Broń Cienistej Sosny', '$N, chcę, żebyś $gzabił:zabiła; tylu trolli Cienistej Sosny, ilu zdołasz. Musimy mocno przetrzebić ich szeregi, zanim zwrócimy uwagę na Ostoję Śmierci. A skoro już przy tym jesteś, upieczmy dwie pieczenie przy jednym ogniu: przynieś mi sporo ich broni. Lepiej, żeby się nie zmarnowała, a my użyjemy jej w walce z Plagą.$B$BUderz mocno na ich obozy na wschodzie i południu – w Zeb\'Tela i Zeb\'Nowa.', 'Zbierz 3 topory łowcy głów, 3 maczugi cieniomaga, 3 pazury władcy kotów i 3 laski rzucacza uroków. Zanieś je kapitanowi Heliosowi w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', 'Wróć do kapitana Heliosa w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9215, 'koKR', 'Przynieś mi głowę Kel\'gasha!', 'POSZUKIWANY: Przynieś głowę Kel\'gasha Nikczemnego, wodza trolli Cienistej Sosny, kapitanowi Heliosowi. Bez zbędnych pytań. Wiadomo, że Kel\'gash przebywa gdzieś na południu, w Zeb\'Nowa.$B$B$B$BNAGRODA: Tak, ale bez zaliczek!', 'Zanieś głowę Kel\'gasha Nikczemnego kapitanowi Heliosowi w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', 'Wróć do kapitana Heliosa w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9216, 'koKR', 'Gnijące serca', 'Słyszałam, że trolle Amani zjadają serca wrogów, by przejąć ich siłę. Może coś w tym jest, $N. Odpowiednio spreparowane serca nieumarłych pozwalają uzyskać potężne eliksiry.$B$BWytrop zombie, które włóczą się po Trupiej Bliźnie, i przynieś mi ich serca. Pokażę ci, jak możemy wzmocnić twoją fizyczną sprawność w walce z nieumarłymi.', 'Przynieś 10 gnijących serc magistrix Aminel w Trankwillienie.', '', 'Wróć do magistrix Aminel w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9217, 'koKR', 'Więcej gnijących serc', '', '', '', 'Wróć do magistrix Aminel na Widmowych Ziemiach.', '', '', '', '', 0),
(9218, 'koKR', 'Pył z kręgosłupa', 'Mroczna energia, która płynie przez ciała ożywionych szkieletów, gromadzi się głównie w ich kręgosłupach. Odkryłam sposób, by zamknąć tę energię w miksturze wzmacniającej nasze zdolności magiczne w walce z nieumarłymi.$B$BPrzynieś mi trochę pyłu z kręgosłupa, a chętnie dam ci próbkę. Szkieletów wałęsających się po Trupiej Bliźnie, na zachód stąd, znajdziesz aż nadto.', 'Przynieś 10 porcji pyłu z kręgosłupa magistrix Aminel w Trankwillienie.', '', 'Wróć do magistrix Aminel w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9219, 'koKR', 'Więcej pyłu z kręgosłupa', '', '', '', 'Wróć do magistrix Aminel na Widmowych Ziemiach.', '', '', '', '', 0),
(9220, 'koKR', 'Wojna z Ostoją Śmierci', 'Jeśli pragniesz wesprzeć naszą sprawę, nie ma lepszego miejsca, by zacząć, niż to, i lepszej chwili niż teraz.$B$BOdbudowując Sanktuarium Słońca, wznieśliśmy sztandar oporu tuż przed siedzibą władzy naszego wroga – Ostoją Śmierci.$B$BRuszaj i walcz z hordami nieumarłych, które zamieszkują tę plugawą twierdzę Plagi.', 'Zabij 5 oczu Dar\'Khana, 6 centurionów Nerubis i 6 zawodzicieli w Ostoi Śmierci, a następnie wróć do magistra Idonisa w Sanktuarium Słońca na Widmowych Ziemiach.', '', 'Wróć do magistra Idonisa w Sanktuarium Słońca na Widmowych Ziemiach.', '', '', '', '', 0),
(9274, 'koKR', 'Duchy utopionych', 'Odkąd sięgam pamięcią, jezioro na północy nawiedzają duchy moich przodków, $N. Te biedne dusze padły ofiarą tragicznego wydarzenia, w którym wielu z nich utonęło na dnie jeziora.$B$BSzczegóły tamtych wydarzeń w większości poszły w zapomnienie, lecz ich upiorne krzyki nieustannie przypominają o ciążącej na nich klątwie.$B$BJeśli podołasz temu zadaniu, idź nad jezioro i połóż kres ich cierpieniu, $N. Zyskasz moją wdzięczność, a także ich... jestem tego pewien.', 'Tropiciel Krenn\'an z Enklawy Obieżyświatów na Widmowych Ziemiach chce, żebyś $gzabił:zabiła; 8 mściwych zjaw i 8 wygłodniałych zjaw w pobliskim jeziorze.', '', 'Wróć do tropiciela Krenn\'ana w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9275, 'koKR', 'Szczypta przyprawy', 'Wypożyczono mnie Obieżyświatom, abym pomógł im uporać się z kłopotem z trollami. Sądzę, że mam na to rozwiązanie.$B$BMam do dyspozycji całe mnóstwo silnych trucizn. Trolle, jak wiesz, to żywe stworzenia, więc muszą jeść. Jeśli połączymy moją truciznę z ich jedzeniem... cóż, jestem pewien, że wyniki będą zabawne!$B$BPomożesz nam pozbyć się trolli Cienistej Sosny z Zeb\'Nowa na południu? Obóz leży po obu stronach, północnej i południowej, drogi do Zul\'Aman.', 'Zatruj zapasy żywności trolli w obozach w Zeb\'Nowa, a następnie wróć do aptekarza Venustusa w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', 'Wróć do aptekarza Venustusa w Enklawie Obieżyświatów na Widmowych Ziemiach.', 'Zatruj stojak z surowym mięsem', 'Zatruj stojak z wędzonym mięsem', 'Zatruj stojak ze świeżymi rybami', '', 0),
(9276, 'koKR', 'Atak na Zeb\'Tela', 'Nasze siły są tu mocno rozproszone, $N, więc twoja pomoc będzie bezcenna. Kapitan powierzył mi nadzór nad nękaniem okolicznych obozów trolli Cienistej Sosny. Naszą zasadą jest nie dawać im wytchnienia aż do dnia, w którym przypuścimy bezlitosną ofensywę i wybijemy ich do nogi.$B$BDo tego czasu potrzebujemy wszystkich ochotników, jakich zdołamy znaleźć, by przetrzebić szeregi trolli Cienistej Sosny.$B$BMyślisz, że dasz radę pójść na wschód, do Zeb\'Tela, i trochę im dopiec?', 'Zabij 8 cieniomagów Cienistej Sosny i 8 łowców głów Cienistej Sosny, a następnie wróć do Obieżyświatki Solanny w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', 'Wróć do Obieżyświatki Solanny w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9277, 'koKR', 'Szturm na Zeb\'Nowa', 'Pora na coś nieco trudniejszego. W Zeb\'Nowa, na południu, mieszkają potężniejsze trolle Cienistej Sosny. W ramach naszych nieustających starań, by ograniczać liczbę trolli do minimum, wysyłam cię tam, byś $gnapadł:napadła; na nich wszelkimi dostępnymi ci sposobami.$B$BCo ty na to, $N? $GGotów:Gotowa; rozprawić się z kolejnymi trollami?', 'Zabij 10 władców kotów Cienistej Sosny i 10 rzucaczy uroków Cienistej Sosny, a następnie wróć do Obieżyświatki Solanny w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', 'Wróć do Obieżyświatki Solanny w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', 0),
(9282, 'koKR', 'Enklawa Obieżyświatów', 'Magistrowie i Obieżyświaci nie zawsze patrzą na świat tak samo, $N. Gdy jednak chodzi o Dar\'Khana, wszyscy się zgadzamy, że trzeba znaleźć sposób, by pokonać jego i jego legiony.$B$BTropicielka Vynna z Enklawy Obieżyświatów, na północny wschód stąd, natrafiła na ważne informacje o naszym wrogu. Porozmawiaj z nią i sprawdź, czy możesz jej w czymś pomóc.', 'Magister Kaendris z Sanktuarium Słońca chce, żebyś $gporozmawiał:porozmawiała; z tropicielką Vynną w Enklawie Obieżyświatów na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9315, 'koKR', 'Anok\'suten', 'Podejdź bliżej, ja... umieram.$B$BPrzysłano mnie tu... bym zabił tych nerubian, ale Vandril nie... wiedział, że mają przywódczynię.$B$B<Umierający krwawy elf odkrztusza sporo krwi.>$B$BMusisz odnaleźć i... zabić Anok\'suten. Sprowadź pomoc. Ona krąży po... Wiosce Słonecznej Korony.', 'Zabij Anok\'suten i wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', 'Wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9327, 'koKR', 'Porzuceni', 'Wiem, że to wydaje się dziwne, ale ci Porzuceni są tu, by pomóc. Porozmawiaj z ich przywódcą, najwyższym egzekutorem Mavrenem. Jest w wieży po zachodniej stronie miasta.$B$BA gdy już z nim porozmawiasz, $N, wróć do mnie – mam sprawę niecierpiącą zwłoki, którą trzeba natychmiast się zająć!', 'Porozmawiaj z najwyższym egzekutorem Mavrenem w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9329, 'koKR', 'Porzuceni', 'Wiem, że to wydaje się dziwne, ale Porzuceni są tu, by pomóc. Porozmawiaj z ich przywódcą, najwyższym egzekutorem Mavrenem. Jest w wieży po zachodniej stronie miasta.$B$BA gdy już z nim porozmawiasz, $N, wróć do mnie – mam sprawę niecierpiącą zwłoki, którą trzeba natychmiast się zająć!', 'Porozmawiaj z najwyższym egzekutorem Mavrenem w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9460, 'koKR', 'Połączone siły', 'Keltus Mroczny Liść melduje się na służbie!$b$bOch... a ty w ogóle kim jesteś? Jeśli $gprzyszedłeś:przyszłaś; po mój raport, nalegam, byś najpierw mi $gpomógł:pomogła;.$b$bZamierzam zaatakować szpiegów Strażniczek, ale na pierwszy ogień chcę posłać moją wierną Szept. Potrzebuje tylko zapachu, by ich namierzyć.$b$bKtoś o twoich umiejętnościach z pewnością zdoła się zakraść i ukraść coś przywódczyni Strażniczek?', 'Keltus Mroczny Liść chce, żebyś $gukradł:ukradła; Koronkową chusteczkę Przywódczyni Strażniczek i $gprzyniósł:przyniosła; mu ją.', '', 'Wróć do Keltusa Mrocznego Liścia w Gaju Wszechpieśni.', '', '', '', '', 0),
(9487, 'koKR', 'Tajemni łupieżcy', 'Tajemni łupieżcy to magiczne twory o czysto fizycznej sile. Są ciężko opancerzeni i zadają ogłuszające ciosy. Ty jednak potrafisz ominąć ich obronę i uniknąć ich ataków. Twoja biegłość w czarach daje ci wiele przewag, $N.$b$bUdaj się do Iglicy Gwiazdy Zarannej i rozbij tajemnych łupieżców w drobny mak. Ze szczątków zbierz skrystalizowane fragmenty magicznej energii i wróć do mnie. Iglica Gwiazdy Zarannej leży na wschodzie, po drugiej stronie jeziora.', 'Arkanista Vandril chce, żebyś $gzebrał:zebrała; dla niego 10 tajemnych fragmentów.', '', 'Wróć do arkanisty Vandrila w An\'daroth na Widmowych Ziemiach.', '', '', '', '', 0),
(9488, 'koKR', 'Prosta szata', 'Tajemne fragmenty, które $gzebrałeś:zebrałaś;, świetnie się nadadzą.$b$bDo czego, pytasz? Do uszycia wspaniałej szaty, godnej kogoś takiego jak ty!$b$bPotrzebujemy jeszcze tylko trochę lnianego płótna i gruczołu jedwabnego wrzecionowego pająka. Gruczoł znajdziesz w każdym wrzecionowym pająku – najlepiej po tym, jak go zabijesz.', 'Arkanista Vandril chce, żebyś $gprzyniósł:przyniosła; mu 15 sztuk lnianego płótna i gruczoł jedwabny wrzecionowego pająka.', '', 'Wróć do arkanisty Vandrila w An\'daroth na Widmowych Ziemiach.', '', '', '', '', 0),
(9491, 'koKR', 'Chciwość', 'Wczoraj przejeżdżał tędy bogaty, powiem więcej, obrzydliwie bogaty kupiec i rozprawiał o jakimś pierścieniu „o ogromnym znaczeniu archeologicznym”, zamkniętym w jednej z niezliczonych skrzyń grobowych w Katakumbach Amanów. A gdy nie mówił o pierścieniu, mówił o tym, ile by za niego zapłacił.$b$bWiesz co? Dam ci złodziejskie narzędzia, a jeśli przyniesiesz ten pierścień, zapłacę ci tyle, że kupisz sobie dziesięć własnych!', 'Eralan z Trankwillienu chce, żebyś $gzdobył:zdobyła; Nadżartą złotą obrączkę z Katakumb Amanów.', '', 'Wróć do Eralan w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(9758, 'koKR', 'Powrót do arkanisty Vandrila', 'A teraz, $gmój przyjacielu:moja przyjaciółko;, zechciej wrócić do arkanisty Vandrila. Wiem, że bardzo mu pilno wysłać cię na twoje pierwsze zadanie tutaj, na Widmowych Ziemiach.$B$BLiczymy na ciebie, $N. Nie zawiedź nas.', 'Wróć do arkanisty Vandrila w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', '', '', 0),
(9877, 'koKR', 'Wzmacniający wywar', 'Walka z Plagą nie obywa się bez ofiar. Każdego dnia wielu ginie, a jeszcze więcej spotyka los gorszy od śmierci.$B$BPlaga często bierze jeńców. Śmierć byłaby lepsza od tego, co czeka ich w Ostoi Śmierci. Przesłuchuje się ich i torturuje, gdy są pod wpływem okropnych trucizn, które łamią wolę.$B$BAptekarz Renzithen z Trankwillienu opracował środek zaradczy. Udaj się do niego i odbierz ten wzmacniający wywar.', 'Porozmawiaj z aptekarzem Renzithenem w Trankwillienie.', '', '', '', '', '', '', 0),
(10548, 'koKR', 'Smutna prawda', 'Pamiętasz, jak ci mówiłam o tym tłustym kupcu, który szukał pierścienia? Okazuje się, że wysłał na poszukiwania swojego syna archeologa i nie skończyło się to najlepiej. A przez „nie najlepiej” mam na myśli, że go zabili i zasuszyli mu głowę.$b$bMoże się to wydać zimne, wyrachowane i wyjątkowo nieczułe, ale kupiec dużo zapłaci, żeby odzyskać głowę syna. Brzmi jak robota w sam raz dla ciebie!$b$bIdź na wschód, aż znajdziesz trollowe ruiny Zeb\'Tela i Zeb\'Nowa. Na pewno znajdziesz ją w którejś z tamtejszych skrzyń.', 'Eralan z Trankwillienu chce, żebyś $gzdobył:zdobyła; Zasuszoną głowę archeologa z jednej ze skrzyń w Zeb\'Tela lub Zeb\'Nowa.', '', 'Wróć do Eralan w Trankwillienie na Widmowych Ziemiach.', '', '', '', '', 0),
(10549, 'koKR', '', '', 'Eralan z Trankwillienu chce, żebyś $gzdobył:zdobyła; Zasuszoną głowę archeologa z jednej ze skrzyń w Zeb\'Tela lub Zeb\'Nowa.', '', '', '', '', '', '', 0),
(11130, 'koKR', 'Ooo, błyskotki!', 'Podejdź bliżej, $gchłopie:złotko;! Niech stary Griftah popatrzy na twoje błyskotki....$b$bHmm. No, no, nieźle, ale stać cię na więcej. Na dużo, dużo więcej.$b$b<Griftah nachyla się i szepcze.>$b$bBezcenne błyskotki są wszędzie, $N, trza tylko wiedzieć, gdzie szukać! Masz szczęśliwy dzień; znam gościa, co pomoże ci znaleźć więcej błyskotek, niż zdołasz unieść.$b$bOdwiedź mojego starego kumpla Budda koło Zul\'Aman i pokaż mu to. Powiedz mu, że przysyła cię stary Griftah, a on dopuści cię do swojego nowego przedsięwzięcia.', 'Griftah chce, żebyś $gzaniósł:zaniosła; Liścik Griftaha Buddowi na Widmowe Ziemie, tuż pod Zul\'Aman.', '', 'Wróć do Budda Nedrecka na Widmowych Ziemiach.', '', '', '', '', 0),
(11132, 'koKR', 'Obiecanki cacanki...', 'Moje przenikliwe teorie potwierdzają pogłoski o ogromnym skarbie w Zul\'Aman. Starczy wierzchowców i rezydencji dla każdego! Ale najpierw to, co najważniejsze. Na swój udział trzeba przecież zapracować....$b$bNasze pierwsze próby nie poszły tak dobrze, jak się spodziewałem. Prawdę mówiąc, moja mapa i rekruci, którym ją pożyczyłem, zaginęli. Polowali na trollową bestię imieniem Nalorakk.$b$bMniejsza o załogę, potrzebuję tej mapy! Uda ci się, a przejdziesz do historii jako ten, kto pomógł Buddowi Nedreckowi odkryć tajemnice Zul\'Aman!', 'Budd Nedreck ze Wzgórz Toporków chce, żebyś $godzyskał:odzyskała; jego mapę z tarasu arcykapłana Nalorakka w Zul\'Aman.', '', 'Wróć do Budda Nedrecka na Widmowych Ziemiach.', '', '', '', '', 0),
(11163, 'koKR', 'Agentka pod przykrywką', '<Donna rozgląda się, po czym szepcze do ciebie.>$b$b$N, to, co ci zaraz powiem, musi zostać między nami, jasne?$b$bPrzysłali mnie Rozjemcy z Shattrath, żebym przeniknęła do tutejszej bandy Budda. Prawdę mówiąc, od chwili twojego przybycia $gbyłeś:byłaś; jedną z kluczowych osób w moim śledztwie.$b$bAle twoje czyny oczyściły cię z wszelkich podejrzeń. Co więcej, za zabicie szalonego wodza, Zul\'jina, czuję się zobowiązana wynagrodzić twoje starania.', 'Zgłoś się do Donny Brascoe po nagrodę za bohaterstwo w Zul\'Aman. Donna stacjonuje obecnie na Widmowych Ziemiach, tuż pod Zul\'Aman.', '', '', '', '', '', '', 0),
(11164, 'koKR', 'Łowcy kłów', 'Ej, mon! Ty tu $gnowy:nowa;, co? Zrób mi przysługę.$b$bBudd ciągle poprawia swoje przebranie za leśnego trolla. Mówi, że już blisko – brakuje mu tylko ostatniego szlifu. Kłów.$b$bMoje talenty do skórowania tu się marnują. Jak mam wyrywać trollom kły, to mnie mdli.$b$bPrzynieś mi 10 trollowych kłów, co, mon?', 'Prigmon potrzebuje, żebyś $gzebrał:zebrała; 10 kłów leśnych trolli od trolli w Zul\'Aman. Zanieś mu je do obozu Budda na Widmowych Ziemiach.', '', 'Wróć do Prigmona na Widmowych Ziemiach.', '', '', '', '', 0),
(11165, 'koKR', 'Troll wśród trolli', 'Słuchaj, mon, jest jeszcze coś do zrobienia dla starego Prigmona.$b$bZungam, mój kuzyn nicpoń, utknął w Zul\'Aman. I jeszcze żyje – dopiero co wczoraj w nocy widziałem jego flarę sygnałową!$b$bPowinienem dać mu zgnić za to, że wpakował mnie w tę kabałę, ale wisi mi kupę forsy.$b$bPomóż mu, jak możesz, a ściąganie długu zostaw mnie!', 'Prigmon zlecił ci odnalezienie swojego kuzyna Zungama gdzieś w Zul\'Aman i udzielenie mu pomocy.', '', '', '', '', '', '', 0),
(11166, 'koKR', 'Krzyżyk na mapie... i na tobie!', 'Jak ci głupcy mogli zawieść? Mówiłem im, żeby uważali – dałem im nawet przebrania, żeby wtopili się w tłum. Ach, cóż. Dobra strona ich porażki jest taka, że ta okazja przypada tobie.$b$bUda ci się, a będziesz na najlepszej drodze, by dołączyć do mojej załogi i dzielić niezmierzoną sławę, która wkrótce stanie się moim udziałem. Nie żebym potrzebował jej więcej, rzecz jasna.$b$bKilka fragmentów mojej mapy wymaga jeszcze dalszego zbadania, zanim będziemy mogli rozpocząć wykopaliska....', 'Wejdź do Zul\'Aman i odwiedź komnatę Halazziego, platformę Jan\'alai i platformę Akil\'zona. Przekaż szczegóły tych miejsc Buddowi w jego obozie na Widmowych Ziemiach.', '', 'Wróć do Budda Nedrecka na Widmowych Ziemiach.', 'Zbadaj komnatę Halazziego', 'Zbadaj platformę Jan\'alai', 'Zbadaj platformę Akil\'zona', '', 0),
(11171, 'koKR', 'Mistrz Uroków? Ha!', 'Znakomicie! Wszystko jest prawie gotowe na moje wielkie wejście do Zul\'Aman.$b$bŚwietnie się $gspisałeś:spisałaś;, $N. Rozmawiałem z załogą i coraz bardziej cię lubią. Powiedziałbym, że już niewiele ci brakuje, by na stałe dołączyć do zespołu. Zostało ci tylko jedno – rozprawić się z tym całym „Mistrzem Uroków”.$b$bNic trudnego, naprawdę. Stań przed tym nędznikiem, a on pewnie po prostu odwróci się i ucieknie. Słabsze, starsze trolle dodają sobie groźnie brzmiące tytuły, żeby nadrobić swoje braki, rozumiesz?$B', 'Budd Nedreck ze Wzgórz Toporków chce, żebyś $gzabił:zabiła; Mistrza Uroków Malakrasa w Zul\'Aman.', '', 'Wróć do Budda Nedrecka na Widmowych Ziemiach.', '', '', '', '', 0),
(11178, 'koKR', 'Krew wodza', 'Gdy przyglądasz się pulsującej fiolce, twoje myśli biegną ku temu małemu, drażliwemu człowieczkowi spod Zul\'Aman.$b$bNie możesz się doczekać, aż zobaczysz minę Budda, gdy to ujrzy!', 'Zanieś Krew Zul\'jina Buddowi do jego obozu na Widmowych Ziemiach, pod Zul\'Aman.', '', 'Wróć do Budda Nedrecka na Widmowych Ziemiach.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9130, 'koKR', 'Lymel chce, żebyś $gpoleciał:poleciała; do Srebrnej Luny i $gprzywiózł:przywiozła; jej towary, tak? Oczywiście. Szybko cię tam dostarczę... za niewielką opłatą, rzecz jasna.', 0),
(9138, 'koKR', 'Znakomicie! Wiele jednak trzeba jeszcze zrobić, zanim Plaga zostanie całkowicie wyparta z potężnego Quel\'Thalas!$B$BProszę, weź te monety... to niewiele, ale $gzasłużyłeś:zasłużyłaś; na nie.', 0),
(9139, 'koKR', 'Twój sukces w Wiosce Złotej Mgły przybliża nas o kolejny krok do odzyskania naszej ziemi. Nie łudź się jednak, $N – ta walka jeszcze długo się nie skończy.$B$BProszę, w pełni na to $gzasłużyłeś:zasłużyłaś;. Może ci się przydać, gdy ruszysz na Wioskę Bieżywiatrów.', 0),
(9140, 'koKR', 'Udało ci się, $N. $GZłamałeś:Złamałaś; władzę Plagi nad trzema wioskami! Teraz łatwiej nam będzie skupić siły przeciw Pladze na Trupiej Bliźnie i dalej na południu, w Ostoi Śmierci.$B$BProszę, wybierz jedną z tych rzeczy. Mam nadzieję, że nigdzie się nie wybierasz? Twoja dalsza pomoc bardzo by nam się przydała!', 0),
(9143, 'koKR', 'Doceniam twoje starania, $N! Dziękuję. Teraz możemy powiedzieć, że ta wyprawa i wszystkie stracone w niej życia nie poszły na marne.', 0),
(9145, 'koKR', 'Dobrze słyszeć, że Lethvalin dotarł w bezpieczne miejsce i że miał dość rozumu, by poprosić cię o pomoc, zamiast tylko tam czekać.$B$BMam nadzieję, że tropicielka Salissa bezpiecznie dotarła do Enklawy Obieżyświatów.', 0),
(9146, 'koKR', 'To doprawdy fatalne wieści – całkowicie przeceniłem zdolności przywódcze Tomathrena. Dopilnuję, by wysłano oddział, który bezpiecznie sprowadzi jego i Valannę.$B$BNiestety, od tropicielki Salissy nie mieliśmy żadnych wieści, więc obawiam się najgorszego.$B$B$GOddałeś:Oddałaś; dziś Obieżyświatom wielką przysługę, $N. Przyjmij jedną z tych rzeczy jako skromny wyraz naszej wdzięczności.', 0),
(9149, 'koKR', 'Doskonale! Te kręgosłupy będą bezcenne dla moich badań! Gdy znajdę lekarstwo na zarazę, a moje imię stanie się sławne, nie omieszkam o tobie wspomnieć!$B$BTymczasem weź to w nagrodę. Może ci się przydać, jeśli postanowisz wrócić na wybrzeże.', 0),
(9150, 'koKR', 'Są niezwykle potężne, $N. Jestem bardzo zadowolony z twojej pracy.', 0),
(9151, 'koKR', 'Przysłał cię Darenis? Niech będzie, przypuszczam, że twoja pomoc w walce z siłami Dar\'Khana może się nam przydać.', 0),
(9152, 'koKR', 'Skoro reszta moich zapasów jest już tutaj, mogę wreszcie otworzyć sklep. Z pewnością najwyższy egzekutor ucieszy się, słysząc, że wojna z Dar\'Khanem i Plagą może się rozpocząć.$B$BJest też, rzecz jasna, drobna kwestia twojego wynagrodzenia. Proszę bardzo, $N, oto monety, o których wspominałem. Zajrzyj koniecznie, gdybyś $gpotrzebował:potrzebowała; jakichś towarów rzemieślniczych.', 0),
(9155, 'koKR', 'Nieźle, $N. Tak trzymaj, przydałoby się tu więcej takich jak ty.', 0),
(9156, 'koKR', 'Ach... Luzran i Zgniłokłykieć! Już nie wyglądacie tak groźnie, co? Choć widzę, że paskudni jesteście jak zawsze.$B$BWeź jedną z tych nagród, $N. $GZasłużyłeś:Zasłużyłaś; na nią.', 0),
(9157, 'koKR', 'Dzięki tym naszyjnikom znów przyzwiemy Aquantiona. Zbuntowany żywiołak zapłaci, a nasza śmierć zostanie pomszczona!', 0),
(9158, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. To ważne, by zaraza nie przeniosła się na zdrowe zwierzęta w Gaju Wszechpieśni. Jeśli szukasz zajęcia, mam dla ciebie więcej pracy.', 0),
(9159, 'koKR', '$GPodszedłeś:Podeszłaś; do zadania z powagą, dlatego chcę cię odpowiednio nagrodzić. Potrzebujemy więcej sojuszników z twoją odwagą i determinacją, $N.', 0),
(9160, 'koKR', 'Szkoda, że plany nocnych elfów nie okazały się w An\'daroth oczywiste. Jednak te przedmioty, które wyglądały jak niewielkie, magicznie wyhodowane drzewka z naładowanymi kulami na szczycie, brzmią interesująco. Wygląda na to, że przy zdobywaniu informacji będziemy musieli działać bardziej bezpośrednio.$B$BProszę, weź te monety i mikstury. Sądzę, że przydadzą ci się, zanim skończymy z tymi nocnymi elfami.', 0),
(9161, 'koKR', 'Po przejrzeniu kilku pierwszych stron tej starej księgi dochodzisz do wniosku, że należała niegdyś do niejakiego Dar\'Khana Drathira.', 0),
(9162, 'koKR', 'Te informacje są bardzo cenne, $N. Wszyscy wiedzieliśmy o planach Dar\'Khana, który chciał wykraść moc Słonecznej Studni dla Plagi, ale wiele z tego, co tu zapisano, jest dla nas zupełną nowością. Magister Kaendris z Sanktuarium Słońca z pewnością zechce to przejrzeć.', 0),
(9163, 'koKR', 'Niepokojące! Te plany pokazują siły nocnych elfów w An\'daroth, o czym już wiedzieliśmy, ale także w An\'owyn, bardziej odległym węźle linii mocy na południowym wschodzie.$B$BJest jeszcze trzeci węzeł, na wschodzie, o którym plany milczą – An\'telas. Mam co do tego wszystkiego bardzo złe przeczucia, $N.', 0),
(9164, 'koKR', 'Doskonała robota, $N. Gdyby nie twoja pomoc, ci więźniowie straciliby rozum i dusze na rzecz Plagi.', 0),
(9166, 'koKR', 'To było po prostu straszne! Nocne elfy! Wyczarowały tu swój księżycowy kryształ w jakimś nikczemnym celu, ale wymknąłem się i zebrałem większy oddział naszych zwiadowców i magów z pobliskiego Sanktuarium Słońca. Zabiliśmy większość z nich, a reszta oddziału ściga niedobitki!$B$BCieszę się, że tu jesteś – zostawiono mi do ochrony zaledwie paru zwiadowców! Tu nie jest bezpiecznie!$B$BDaj mi chwilę, przeczytam te plany i zobaczę, co knują nocne elfy.', 0),
(9167, 'koKR', '$GZadałeś:Zadałaś; dziś śmiertelny cios władzy Plagi w tym regionie.$B$BSkoro nikczemnego zdrajcy już nie ma, niedługo odzyskamy nasze ziemie i przywrócimy naszą dawną wielkość.', 0),
(9169, 'koKR', 'Co za ulga, $N! Zapewniam cię, że gdybyś nie $gwyłączył:wyłączyła; tych kryształów wieszczących, nasze położenie byłoby jeszcze bardziej niepewne niż teraz! Pomyśl tylko: otoczeni przez wrogów, a jeden z nich mógłby śledzić każdy nasz ruch!$B$BAle dzięki tobie nie musimy się już o to martwić! Proszę, weź to. Chcę, byś $gzostał nagrodzony:została nagrodzona; za swoje starania, a tak się składa, że mam tu kilka rzeczy, które nie są mi już do niczego potrzebne.$B$BJeszcze raz dziękuję, $N!', 0),
(9170, 'koKR', 'Armie Dar\'Khana wkrótce upadną. Plaga nie ma szans wobec połączonej potęgi sin\'dorei i Porzuconych.', 0),
(9171, 'koKR', 'No dobrze, muszą wystarczyć. Nie, nie opisuj mi, jak łaziły, nie chcę tego wiedzieć! Dokonam na tych odnóżach swoich czarów i wyjdą całkiem smaczne. Odrobina przypraw tu, szczypta ziół tam, do tego rzecz jasna kilka tajemnych składników i voilà – danie godne królowej... a w tym wypadku damy.$B$BTwoje usługi były zadowalające, $N. Proszę, weź ten przepis i kilka próbek.', 0),
(9172, 'koKR', 'Ta księga... to niemożliwe! To pismo samego Dar\'Khana. Muszą tu być informacje, które odsłonią słabość naszego wroga.$B$BDobrze $gzrobiłeś:zrobiłaś;, przychodząc z tym do nas, $N. Obieżyświaci wykazali się wielką mądrością, oddając tę sprawę w nasze ręce. Ten pancerz powinien pomóc ci wspierać naszą sprawę.', 0),
(9173, 'koKR', 'Nie wątpię, że Lady Sylwana ucieszy się, słysząc, że poczyniliśmy w tej sprawie postępy.$B$BProszę, weź te monety jako zapłatę za twoje starania.', 0),
(9174, 'koKR', '$GPomściłeś:Pomściłaś; naszą śmierć i $gzerwałeś:zerwałaś; uścisk, w którym Aquantion trzymał nasze dusze. Wreszcie możemy zaznać spoczynku.', 0),
(9175, 'koKR', 'Mówisz, że $gznalazłeś:znalazłaś; go przy jednym ze sług Plagi w Iglicy Bieżywiatrów i że jest na nim inskrypcja? Pokaż!$B$BProszę, weź te monety za dobrze wykonaną robotę.', 0),
(9176, 'koKR', 'Plotki były prawdziwe! Kamień światła i kamień płomienia naprawdę istnieją! Użyjemy ich mocy, by wykuć broń przeciw Dar\'Khanowi.$B$BUżyj ich, gdy nadejdzie właściwa chwila, a uwięziona w nich energia Słonecznej Studni pokona go tą samą mocą, którą chciał nam wykraść!', 0),
(9192, 'koKR', 'Niezła rzeźnia, $N. Teraz przywrócimy górników do pracy. Pewnie będą zawiedzeni, że przerwa się skończyła, ale trzeba wykuwać zbroje i broń, a do tego potrzebna jest ruda.$B$BProszę, weź to jako zapłatę za wypełnienie obowiązku. Idź naprawić zbroję i broń, a potem wypij coś na mój koszt.', 0),
(9193, 'koKR', 'Odrażające, lecz zapewniam cię, że konieczne. $GOddałeś:Oddałaś; nam wielką przysługę, badając tę sprawę. Proszę, przyjmij to jako wyraz naszej hojności i uznania.', 0),
(9199, 'koKR', 'Mumie wskrzeszane przez trollich kapłanów... sprytne! Trolle Cienistej Sosny muszą próbować zasilić swoje szeregi za pomocą nekromancji. Założę się, że te wyrocznie używały juju w swoim rytuale ożywiania.$B$BPo raz kolejny wypełniasz obowiązek, jak przystało komuś o twojej rosnącej sławie. Przyjmij to z naszą wdzięcznością.', 0),
(9207, 'koKR', 'Moja uczennica nie potrafiła sama się tym zająć? W takim razie zamienię z nią słówko, gdy wróci – gnole czy nie gnole. Skoro już o tym mowa, czemu nie wróciła z tobą?$B$B<Magister wzdycha.>$B$BZ nią są same kłopoty; należyte wyszkolenie jej będzie nie lada wyzwaniem. Dziękuję, że $gprzyniosłeś:przyniosłaś; mi te próbki. Mamy nadzieję odkryć w nich jakąś szczególną właściwość, która pomoże w walce z Plagą.$B$BProszę, przyjmij te monety jako wyraz mojego uznania.', 0),
(9212, 'koKR', 'Jesteś $gprawdziwym bohaterem:prawdziwą bohaterką;, $N, skoro $gwyciągnąłeś:wyciągnęłaś; ją stamtąd żywą. Chyba będziemy musieli przypuścić natarcie, żeby oczyścić i te katakumby. Jakbyśmy nie mieli dość kłopotów z żywymi trollami!$B$B$GDokonałeś:Dokonałaś; dziś wielkiej rzeczy, należy ci się nagroda. Wybierz, co chcesz, spośród tych rzeczy.', 0),
(9214, 'koKR', 'Natychmiast wyślę kilku tropicieli, by ocenili spustoszenie, jakie $gpoczyniłeś:poczyniłaś; wśród trolli Cienistej Sosny. Jeśli te bronie świadczą o twoim sukcesie, nie wątpię, że zdołamy dokończyć dzieła po twojej ofensywie i wkrótce uderzyć na Plagę.$B$BProszę, weź te monety jako zapłatę. I tak palą mi dziurę w sakiewce.', 0),
(9215, 'koKR', 'Ach. A więc to głowa Kel\'gasha tak cuchnęła. Kawał dobrej roboty, $N!$B$BPo śmierci wodza trolle Cienistej Sosny powinny pogrążyć się w kompletnym chaosie. W połączeniu z twoimi niedawnymi wysiłkami, które przetrzebiły ich szeregi, to doskonała okazja, by przypuścić kontrofensywę i wybić ich raz na zawsze.$B$BMasz moją wdzięczność. Może zainteresuje cię któraś z tych rzeczy?', 0),
(9216, 'koKR', 'Weź ten wywar, $N. Gdy go wypijesz, twoja fizyczna siła w walce z Plagą wzrośnie. Jeśli potrzebujesz więcej niż tę próbkę, przynieś mi więcej serc.', 0),
(9217, 'koKR', 'To zapewni ci większą moc w walce z Plagą. Jeśli znajdziesz więcej serc, przynieś je, $N.', 0),
(9218, 'koKR', 'Weź to, $N. Od razu poczujesz różnicę!$B$BŚmiało przynoś więcej pyłu z kręgosłupa – przyda mi się każda ilość, jaką zdołasz dostarczyć. Skutki uboczne? Może trochę zaczną ci strzykać stawy. Nic trwałego, zapewniam!', 0),
(9219, 'koKR', 'Ten pył jest równie silny jak zawsze, $N. Przynoś mi go dalej, jeśli chcesz wzmocnić swoje moce magiczne w walce z Plagą.', 0),
(9220, 'koKR', 'Plaga poczuła nasz gniew, $N. Już niedługo ich przeklęta cytadela legnie w gruzach.$B$BSkoro ich szeregi są osłabione, czas uderzyć na cele o większym znaczeniu strategicznym.', 0),
(9274, 'koKR', 'Doceniam twoją pomoc, $N. Boli mnie widok duchów moich przodków w tak żałosnym stanie. Oby wreszcie zaznały spoczynku, na który zasługują.', 0),
(9275, 'koKR', 'Ach, znakomicie! Wiedziałem, że dostarczenie trucizny przez kogoś takiego jak ty okaże się najskuteczniejszym sposobem jej podania. Przy odrobinie szczęścia trolle Cienistej Sosny utyją na niej, zanim padną trupem. To powinno odciągnąć je od Obieżyświatów, a mnie pozwolić wrócić do Trankwillienu.$B$BPraca z tobą była prawdziwą przyjemnością, $N!', 0),
(9276, 'koKR', 'Dobrze, dobrze! Świetnie sobie z tym $gporadziłeś:poradziłaś;! Zobaczmy, czy podołasz teraz czemuś nieco trudniejszemu.', 0),
(9277, 'koKR', 'Niewiarygodne! Naprawdę $gpowinieneś:powinnaś; porozmawiać z kapitanem o wstąpieniu do Obieżyświatów.$B$BNo dobrze, $N, $gdałeś:dałaś; nam wytchnienie, którego potrzebowaliśmy, by dalej gromadzić tu siły. Właściwie, z tego, co mówisz, prawie nie zostało już tych trolli! Może teraz połączymy siły z Trankwillienem i uderzymy na Ostoję Śmierci?$B$BChyba $gzasłużyłeś:zasłużyłaś; na mały upominek. Wybierz coś.', 0),
(9281, 'koKR', 'Dzięki za pomoc, $N. Na samą myśl o zapuszczaniu się do lasu tak blisko Ostoi Śmierci ogarniał mnie strach.', 0),
(9282, 'koKR', 'Przysłał cię Kaendris? Możliwe, że mam dla ciebie zadanie, $N.', 0),
(9315, 'koKR', 'Przepraszam za marne rozpoznanie, $N. Gdybym wcześniej wiedział o tej Anok\'suten, z pewnością bym ci powiedział.$B$BNasze siły są zbyt rozproszone, a wiele rzeczy umyka nam z pola widzenia!', 0),
(9327, 'koKR', 'Wiem, że my, Porzuceni, wydajemy się twoim oczom potworni, ale zapewniam cię, że nie chcemy krzywdy twojego ludu. Jesteśmy tu z powodu wspólnego wroga: zdrajcy Dar\'Khana! Powrócił i teraz ze swojej twierdzy, Ostoi Śmierci na południu, dowodzi Plagą, która najeżdża tę krainę.$B$BNasza przywódczyni, Lady Sylwana Bieżywiatr, pochodzi z tych ziem i w istocie była niegdyś elfką. Ma z Dar\'Khanem stare porachunki i pragnie jego śmierci tak samo jak twój lud.$B$BRazem go pokonamy, $N!', 0),
(9329, 'koKR', 'My, Porzuceni, jesteśmy tu, bo z krwawymi elfami łączy nas wspólny wróg: Dar\'Khan! Powrócił i teraz ze swojej twierdzy, Ostoi Śmierci na południu, dowodzi Plagą, która najeżdża tę krainę.$B$BLady Sylwana Bieżywiatr, która pochodzi z tych ziem i była niegdyś elfką, ma z Dar\'Khanem stare porachunki i pragnie jego śmierci!$B$BPokonamy go, $N, a ty nam w tym pomożesz!', 0),
(9460, 'koKR', 'Znakomicie! Tak osobisty przedmiot silnie przesiąkł zapachem intruzów – wystarczy, by poprowadzić Szept prosto w ich szeregi...', 0),
(9487, 'koKR', 'Co za marnotrawstwo, używać magii do tworzenia istot o sile czysto fizycznej. Zawsze sądziłem, że właśnie po to sprzymierzyliśmy się z pośledniejszymi rasami.$B$BDobrze, że je $gzniszczyłeś:zniszczyłaś; – teraz to, co z nich zostało, wykorzystamy w bardziej stosownym celu.', 0),
(9488, 'koKR', 'Naprawdę nie musisz znać zawiłości szycia magicznej szaty, $N – wystarczy, że wiesz, co mi przynieść.$B$BI powiem szczerze: $gprzyniosłeś:przyniosłaś; tyle, że starczy na kilka szat. Zysk, który z tego wyciągnę, z nawiązką pokryje koszt twojej szaty, a nawet starczy, żebym kupił sobie coś ładnego. Wygląda na to, że to ja powinienem ci dziękować!', 0),
(9491, 'koKR', 'To ten pierścień? Nie ma na co patrzeć, ale wiesz, jak to mówią: co dla jednego elfa śmieć...$B$BI nie zapominajmy o twojej zapłacie. Nie krępuj się wydać jej od razu tutaj, złotko!', 0),
(9758, 'koKR', 'Och, dobrze, jesteś! I w samą porę... jest mnóstwo do zrobienia!', 0),
(9877, 'koKR', 'Janeda wysyła cię na ratunek więźniom z Ostoi Śmierci? Musi mieć o tobie bardzo wysokie mniemanie, $N.', 0),
(10548, 'koKR', 'Och, rany. Nie jest to ładny widok. Kupiec na pewno doceni ją bardziej niż ja.$B$BW ramach zapłaty kupiec zaproponował, że kupi dla ciebie jeden z moich specjalnych towarów, więc wybieraj, złotko!', 0),
(11130, 'koKR', '<Budd czyta liścik.>$B$BAch! $gPrzyjaciel:Przyjaciółka; Griftaha? Witaj!$B$BMasz nienaganne wyczucie czasu, $gprzyjacielu:przyjaciółko;. Tak się złożyło, że niedawno straciłem ostatnich wspólników. Tragedia, doprawdy, ale wielkie nagrody często mają wysoką cenę. Nie ma co rozpamiętywać złego!$B$BZ pewnością $gsłyszałeś:słyszałaś; o moich niezliczonych wyczynach i odkryciach. Otóż wszystko to było niczym w porównaniu z tym! Prawda jest taka, że jesteśmy tu, w Zul\'Aman, o krok od zapisania się w historii, a ty, zrządzeniem losu, jesteś w tym od samego początku!', 0),
(11132, 'koKR', '<Budd wygląda na nieco zaskoczonego.>$b$bOch? $GZnalazłeś:Znalazłaś; ją?$b$bEkhm, to znaczy, oczywiście, że tak! Dobra robota, $N.$b$bZobaczmy, czy znajdę dla ciebie coś miłego... ach tak, to powinno wystarczyć.', 0),
(11163, 'koKR', '<Donna rozgląda się, po czym szepcze do ciebie.>$B$B$N, to, co ci zaraz powiem, musi zostać między nami, jasne?$B$BPrzysłali mnie Rozjemcy z Shattrath, żebym przeniknęła do tutejszej bandy Budda. Prawdę mówiąc, od chwili twojego przybycia $gbyłeś:byłaś; jedną z kluczowych osób w moim śledztwie.$B$BAle twoje czyny oczyściły cię z wszelkich podejrzeń. Co więcej, za zabicie szalonego wodza, Zul\'jina, czuję się zobowiązana wynagrodzić twoje starania.', 0),
(11164, 'koKR', 'Ooo tak, właśnie tego mi trza!$B$BOto zapłata, co ci obiecałem, $N.', 0),
(11165, 'koKR', 'Jestem wolny!$B$BZabrali mi prawie wszystko, jak mnie capnęli, ale masz – weź ostatnie moje monety za fatygę.$B$BI przynajmniej tyle mogę zrobić, że zostanę tu i zaoferuję swoje usługi....', 0),
(11166, 'koKR', '<Budd z trudem zachowuje spokój.>$B$BEee... A więc, $N... najwyższy czas, $gżebyś wrócił:żebyś wróciła;. Tak, w rzeczy samej, wstrzymujesz całą operację.$B$BA zatem uzupełnijmy tę mapę....', 0),
(11171, 'koKR', 'Nareszcie! Teraz, gdy lżejsza robota jest już za nami, mogę wreszcie po raz kolejny zapisać się na kartach historii. Najpierw jednak jest jeszcze jedna drobna sprawa – ty....$B$BObawiam się, $N, że nadszedł czas, bym cię zwolnił. Czuję, że $gosiągnąłeś:osiągnęłaś; tu swój pełny potencjał, jeśli nie $gprzekroczyłeś:przekroczyłaś; go znacznie.$B$BAle nie przejmuj się. W końcu trzeba wyjątkowej osoby, by uczestniczyć w tak niezwykłych wydarzeniach i nie postradać zmysłów. I proszę, mam dla ciebie drobiazg na pamiątkę.', 0),
(11178, 'koKR', 'K-krew samego Zul\'jina, powiadasz?$B$B<Budd bierze się w garść i mówi dalej.>$B$BCóż, doceniam ten gest, $N, ale z łatwością bym go pokonał. Nie ma mowy, żeby był tak straszny, jak mówią legendy. Takie rzeczy zwykle są strasznie przesadzone, jak się z czasem przekonasz. Pewnie ten żałosny stary kretyn po prostu nie mógł się ruszać przez artretyzm!$B$BTak czy owak, to chyba najmniej, co $gmogłeś:mogłaś; zrobić w zamian za życzliwość, jaką ci tu okazałem.$B$BA teraz zmykaj – muszę się pozbyć tej paskudnej probówki!', 0),
(11774, 'koKR', 'Zbezcześć wielkie ognisko Hordy na Widmowych Ziemiach!', 0),
(11850, 'koKR', 'Uczcij płomień Widmowych Ziem!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9130, 'koKR', 'Tak? Cóż to takiego?', 0),
(9138, 'koKR', 'Z twoją pomocą powstrzymamy Plagę, $N. Dar\'Khan jeszcze za wszystko zapłaci!$B$B$GUporałeś:Uporałaś; się już z nerubianami w Wiosce Słonecznej Korony?', 0),
(9139, 'koKR', 'Przez czas spędzony tutaj wiele się nauczyłem o walce z Plagą. Da się ją odeprzeć, ale trzeba to robić małymi krokami. Plaga w plugawy sposób wciela twoich poległych do własnych szeregów jako świeżo powstałych, dlatego po drodze nie wolno ci popełnić żadnego błędu.$B$BJak więc idzie walka o Wioskę Złotej Mgły?', 0),
(9140, 'koKR', '$N, czy Wioska Bieżywiatrów została już wyzwolona? Ci przeklęci magistrowie z Sanktuarium Słońca bez przerwy mnie besztają, bo chcą dostać szczątki Plagi, o których zebranie cię prosiłem.$B$BAle nie przejmuj się tym. Nie spiesz się i zrób wszystko jak należy. Z magistrami sam sobie poradzę.', 0),
(9143, 'koKR', 'Masz już te uszy trolli?$B$BWiesz, gdyby Trankwillien choć od czasu do czasu przysłał nam pomoc, nie byłoby tego kłopotu. Po prostu cieszę się, że tu jesteś.', 0),
(9149, 'koKR', '$GZdobyłeś:Zdobyłaś; okazy, o które prosiłem, $N?', 0),
(9150, 'koKR', '$GZdobyłeś:Zdobyłaś; esencje, $N?', 0),
(9152, 'koKR', 'Gdy tylko dostanę resztę zapasów, otworzę interes. Tutejsze siły daleko nie zajdą, jeśli nie będą mogły kupić tego, czego potrzebują do swojego rzemiosła.$B$BStrefy wojny potrafią być niezwykle dochodowe, nie sądzisz, $N? A teraz powiedz, czy $gprzebiłeś:przebiłaś; się do mojego wozu przez te wszystkie ghule?', 0),
(9155, 'koKR', '$GSkończyłeś:Skończyłaś; już zadanie?', 0),
(9157, 'koKR', '$GZdobyłeś:Zdobyłaś; medaliony? Topielcy wciąż nawiedzają to jezioro!', 0),
(9158, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(9159, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(9160, 'koKR', '$N, jakie wieści przynosisz z An\'daroth? Co knuły tam nocne elfy?', 0),
(9162, 'koKR', 'Powiedz mi, $N, czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(9163, 'koKR', 'Jak postępuje odkrywanie spisku nocnych elfów na Wyspie Shalandis, $N?', 0),
(9164, 'koKR', 'Co się stało z więźniami w Ostoi Śmierci? $GZapuściłeś:Zapuściłaś; się już tam?', 0),
(9166, 'koKR', 'Och, dzięki niebiosom, że jesteś!', 0),
(9167, 'koKR', 'A zatem stało się? Dar\'Khan został zniszczony?', 0),
(9169, 'koKR', 'Czy to już koniec, $N? $GWyłączyłeś:Wyłączyłaś; księżycowy kryształ nocnych elfów w An\'owyn?', 0),
(9170, 'koKR', 'Czy $gzdołałeś:zdołałaś; przeciąć łańcuch dowodzenia Plagi, $N? Porucznicy Dar\'Khana nie żyją?', 0),
(9171, 'koKR', 'Zdaje się, że słyszę burczenie w brzuchu damy nawet stąd! Rozumiem, że rozmawiasz ze mną, bo masz to, o co cię prosiłem?', 0),
(9173, 'koKR', 'Ufam, że wracasz z wieścią, iż Iglica Bieżywiatrów została oczyszczona z plugastwa Plagi?', 0),
(9174, 'koKR', 'Czy Aquantion został już zniszczony?', 0),
(9175, 'koKR', 'Co tam masz?', 0),
(9176, 'koKR', '$GOdzyskałeś:Odzyskałaś; już kryształy?', 0),
(9192, 'koKR', 'Dobre wieści czy złe, $gzłociutki:złociutka;?', 0),
(9193, 'koKR', 'To wyjątkowo ponura i niegodna sprawa. Ufam, że wykonasz to zadanie ku pełnemu zadowoleniu milady?', 0),
(9199, 'koKR', 'Nie muszę ci przypominać, że nie stać nas na kłopoty z trollimi truposzami, którzy powstają tuż pod naszym nosem! Dość mamy kłopotów z Ostoją Śmierci na południu!', 0),
(9207, 'koKR', 'W czym mogę ci pomóc?', 0),
(9214, 'koKR', 'Masz już te bronie? Skoro szeregi Cienistej Sosny są przetrzebione, wreszcie będziemy mogli skupić się na walce z Plagą.', 0),
(9215, 'koKR', 'Co to za okropny smród?', 0),
(9216, 'koKR', 'Masz serca zombie, o które prosiłam, $N?', 0),
(9217, 'koKR', '$GPrzyniosłeś:Przyniosłaś; więcej serc ghuli? Przydadzą mi się wszystkie, jakie zdołasz zebrać, $N.', 0),
(9218, 'koKR', 'Masz próbki, o które prosiłam, $N?', 0),
(9219, 'koKR', '$GZdobyłeś:Zdobyłaś; więcej pyłu z kręgosłupa? Przyda mi się każda ilość, jaką przyniesiesz.', 0),
(9220, 'koKR', '$GWróciłeś:Wróciłaś; z Ostoi Śmierci z tarczą, $N?', 0),
(9274, 'koKR', '$GZrobiłeś:Zrobiłaś;, o co cię prosiłem, $N?', 0),
(9275, 'koKR', 'Czyż to nie ekscytujące? Naprawdę jestem dumny ze swojej pracy; mam nadzieję, że ją doceniasz, $N.$B$BUfam zatem, że $gprzyprawiłeś:przyprawiłaś; jedzenie w obozach trolli w Zeb\'Nowa?', 0),
(9276, 'koKR', 'Jak ci idzie atak na Zeb\'Tela?', 0),
(9277, 'koKR', 'Czy twój szturm na Zeb\'Nowa już się zakończył?', 0),
(9281, 'koKR', '$GZałatwiłeś:Załatwiłaś; sprawę, o której rozmawialiśmy, $N?', 0),
(9315, 'koKR', 'Przywódczyni nerubian? Żaden z oddziałów zwiadowczych nie wspomniał o żadnej Anok\'suten!', 0),
(9329, 'koKR', 'Wiem, że to wydaje się dziwne, ale Porzuceni są tu, by pomóc. Porozmawiaj z ich przywódcą, najwyższym egzekutorem Mavrenem. Jest w wieży po zachodniej stronie miasta.$B$BA gdy już z nim porozmawiasz, $N, wróć do mnie – mam sprawę niecierpiącą zwłoki, którą trzeba natychmiast się zająć!', 0),
(9460, 'koKR', 'Masz coś?', 0),
(9487, 'koKR', 'Mam nadzieję, że nie $gpodszedłeś:podeszłaś; za blisko do tych osiłków?', 0),
(9488, 'koKR', 'Bez potrzebnych materiałów szaty nie da się ukończyć. Ale przecież o tym wiesz, prawda?', 0),
(9491, 'koKR', 'Powiedz mi, że $gznalazłeś:znalazłaś; pierścień. Ten kupiec niedługo znajdzie sobie kogoś innego do tej roboty.', 0),
(10323, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(10365, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(10548, 'koKR', 'Jak idzie polowanie na głowę?', 0),
(10587, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(10687, 'koKR', '$GWykonałeś:Wykonałaś; zadanie, o które cię prosiłam, $N?', 0),
(11130, 'koKR', '<Budd podejrzliwie przygląda się liścikowi.>$B$BCo tam masz?', 0),
(11132, 'koKR', 'Ach tak, $N, prawda?$b$b$GOdzyskałeś:Odzyskałaś; już moją mapę?', 0),
(11164, 'koKR', 'Pospiesz się, mon!$B$BJak nie dam Buddowi tych kłów, i to szybko, to wyśle mnie samego do Zul\'Aman, żebym testował jego maskę!', 0),
(11166, 'koKR', 'Ufam, że moje ręcznie wykonane przebrania zapewniły ci w Zul\'Aman należytą ochronę.$B$B$GZbadałeś:Zbadałaś; dla mnie te miejsca? Czy mam zacząć szukać kogoś na twoje miejsce?', 0),
(11171, 'koKR', 'Mam nadzieję, że doceniasz ogrom szansy, jaką ci dałem, Diedthreexs.$B$B$GUporałeś:Uporałaś; się już ze starym Malakrasem?', 0),
(11178, 'koKR', '<Budd próbuje ukryć niezadowolenie z twojej obecności.>$B$BZnowu ty....$B$BNie wiem, jak to powiedzieć inaczej – jestem zbyt zajęty przygotowaniami, by dłużej cię niańczyć.$B$BZaufaj mi, $N, tak będzie najlepiej. Może jakimś cudem kiedyś wyrobisz sobie nazwisko.$B$BJeśli tak, będziesz $gmógł:mogła; mówić, że $gzaczynałeś:zaczynałaś; u niezrównanego Budda Nedrecka!', 0);
