(27687, 'koKR', 'Przepis: kąski z nietoperza', 'Uczy przyrządzania kąsków z nietoperza.', 0),
(27940, 'koKR', 'Cudowny szalokamień nieśmiertelności', 'Kotwiczy twojego ducha w świecie, dzięki czemu możesz wrócić nawet po najstraszliwszej śmierci, gdy tylko twoja esencja powróci tam, gdzie zginęła!', 0),
(27941, 'koKR', 'Współczujący przyjaciel zwierzaków', 'Ten amulet trzyma groźne zwierzaki z dala. Jego potężna magia ochronna chwilowo słabnie, jeśli skrzywdzisz zwierzaka.', 0),
(27944, 'koKR', 'Talizman trafnego tropienia skarbów', 'Nosząc go, można znaleźć najrzadsze przedmioty w najzwyklejszych miejscach!', 0),
(27945, 'koKR', 'Rekini ząb autentycznej płynnej mobilności', 'Pozwala poruszać się po morzach z największą łatwością.', 0),
(27976, 'koKR', 'Wypolerowany wisior jadalnej energii', 'Skupiając przemianę materii, ten wisior pozwala czerpać wielką energię ze zwykłego jedzenia i picia, a nawet leczyć rany!', 0),
(27978, 'koKR', 'Mydło na sznurku', 'Przygody to żadna wymówka, żeby chodzić brudnym. Teraz możesz nosić mydło wszędzie ze sobą!', 0),
(27979, 'koKR', 'Kamień kolosalnych kangurzych kroków', 'Zwykły kamień, który pozwala noszącemu przeskakiwać przeszkody i małe szczeliny!', 0),
(27982, 'koKR', 'Urok potężnych i porywających pasji', 'Noszony zdobędzie dla ciebie obiekt twych pragnień. Gwarantowane!', 0),
(27992, 'koKR', 'Niezawodna ochrona przed tikbalangami', 'Z tym niezawodnym talizmanem ochronnym żaden tikbalang cię nie znajdzie i nie porwie na wierzchołki drzew. To naprawdę działa!', 0),
