(33010, 'koKR', 'Liścik Griftaha', 'Może uda ci się zerknąć bez łamania pieczęci...', 0),
(33012, 'koKR', 'Bez z Terokkaru', 'Rzadki i wykwintny... jak wszystkie pozostałe.', 0),
(33013, 'koKR', 'Mapa Zul\'Aman od Budda', 'Ta mapa jest w najlepszym razie pobieżna...', 0),
(33014, 'koKR', 'Przedni patyk do szturchania', 'Wykonany rękami natury przez setki lat!', 0),
(33083, 'koKR', 'Orczy grog', 'To nie wychodzi na zdrowie...', 0),
(33102, 'koKR', 'Krew Zul\'jina', 'Przez szkło fiolki czujesz, jak wiruje krew wodza.', 0),
(33106, 'koKR', 'Kieł leśnego trolla', '', 0),
(33298, 'koKR', 'Ostrze uderzeniowe drapieżcy', '', 0),
(33307, 'koKR', 'Formuła: zaklęcie broni – kat', 'Uczy trwałego zaklinania broni do walki wręcz, by czasem dawała 120 pkt. wskaźnika przebicia pancerza. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(33388, 'koKR', 'Bez serca', '', 0),
