INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3031, 'koKR', 'Słuchaj no, Budd!\n\nTo ostatni głupiec, jakiego ci przysyłam, póki nie oddasz mi wszystkiego, co wisisz.\n\nKoniec z wykrętami!\n\nGriftah', 0);
