INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1150, 'koKR', '%s w panice próbuje uciec!', '%s w panice próbuje uciec!', 0),
(12097, 'koKR', 'Najwyższy egzekutor i Dama Złotonośna każą mi czekać, a ja nie mam na to czasu! Moi przyjaciele tam giną, $N!', '', 0),
(12098, 'koKR', '', 'Ponad dzień temu wysłałam tropicielkę Salissę na południe, do enklawy, a tropiciela Lethvalina na zachód, do Trankwillienu! $GWidziałeś:Widziałaś; któreś z nich? Czy to ty jesteś pomocą, którą nam przysłano?', 0),
(12103, 'koKR', 'Co cię tu sprowadza, $N?', '', 0),
(12106, 'koKR', 'Ach, witaj, $N. Jak widzisz, jeszcze nie otworzyłem interesu. A teraz wybacz, jestem bardzo zajęty.', '', 0),
(12107, 'koKR', 'Cóż za radość znów cię widzieć, $N. Nie, naprawdę. To dzięki tobie zarabiam tu krocie.$B$BCo mogę ci dziś sprzedać?', '', 0),
(12108, 'koKR', '', 'Witaj w Trankwillienie, $N. Przepraszam za stan, w jakim go zastajesz. Jak widzisz, mieliśmy pewne kłopoty, ale Porzuceni i ich pani, Lady Sylwana Bieżywiatr, łaskawie udzielili nam w potrzebie wielkiej pomocy.$B$BJeśli możesz pomóc, nie wahaj się. Przyda nam się każda pomoc w walce z niezliczonymi siłami, które stanęły przeciw nam.', 0),
(12115, 'koKR', 'Uwaga... nocne elfy wróciły!', '', 0),
(12129, 'koKR', 'Jak mam pracować w takich warunkach?! I jeszcze ci wszyscy obrzydliwi Porzuceni wokoło! Płaczę nad Trankwillienem i nad Quel\'Thalas!', '', 0),
(12158, 'koKR', '<Krwawy elf szybko odzyskuje przytomność, gdy wlewasz mu wywar do ust.>$B$BZawdzięczam ci życie, $N. Gdyby nie twoja pomoc, nie przetrwałbym bolesnych tortur Plagi.', '', 0),
(12159, 'koKR', '<Podaj wzmacniający wywar.>', '<Podaj wzmacniający wywar.>', 0),
(12160, 'koKR', '<Krwawy elf leży na podłodze w czymś w rodzaju sztucznie wywołanego odrętwienia.>', '', 0),
(12162, 'koKR', 'Możesz już iść. Droga do wyjścia jest bezpieczna.', 'Możesz już iść. Droga do wyjścia jest bezpieczna.', 0),
(12163, 'koKR', '', '<Porzucona leży zwinięta na podłodze, z twarzą wykrzywioną grymasem. Wygląda na to, że w tej chwili nie zdoła wstać o własnych siłach.>', 0),
(12164, 'koKR', '', 'Aaaach... ten ból głowy mnie wykończy.$B$BPewnie przysłali cię, żeby mnie uratować. Długo im to zajęło! Masz ty pojęcie, co tu robią z więźniami?', 0),
(12165, 'koKR', 'Niezbyt wdzięczna z ciebie osoba, co? Droga do wyjścia wolna, uciekaj szybko!', 'Niezbyt wdzięczna z ciebie osoba, co? Droga do wyjścia wolna, uciekaj szybko!', 0),
(12166, 'koKR', '<Krwawy elf leży bezwładnie na stole. Wciąż oddycha, ale najwyraźniej padł ofiarą silnych toksyn usypiających.>', '', 0),
(12168, 'koKR', '<Varnis gwałtownie kaszle, gdy wzmacniający wywar zaczyna działać.>$B$BDziękuję, że mnie $guratowałeś:uratowałaś;. Muszę natychmiast wracać do Trankwillienu!', '', 0),
(12169, 'koKR', 'Powiewy świeżego powietrza, które od czasu do czasu wieją od strony Gaju Wszechpieśni, naprawdę psują mi żołądek, jeśli wiesz, co mam na myśli.', '', 0),
(12170, 'koKR', 'Szukam próbki twojego wzmacniającego wywaru, aptekarzu.', 'Szukam próbki twojego wzmacniającego wywaru, aptekarzu.', 0),
(12171, 'koKR', '', 'Jeśli chcesz mówić o sprawie wagi państwowej, $N, stosowniej będzie poprosić o audiencję u Damy Złotonośnej. Ostrzegam jednak, że jest bardzo zajęta i możesz się naczekać.', 0),
(12179, 'koKR', '', 'Czeka nas ważna praca, $N. Uderzmy na wrogów, póki nie mają się na baczności. Pokażmy im, że zemsta sin\'dorei nigdy nie zapomina ani nie wybacza.', 0),
(12181, 'koKR', '', 'No to mamy kłopot! Jak mam zebrać próbki rudy dla magistrów, skoro kopalnie opanowało to gnolowe robactwo?', 0),
(12183, 'koKR', 'Gdzie ona się mogła podziać? Dość dawno temu wysłałem moją uczennicę, Shatharię, do Kopalni Podziemnego Światła na zachodzie. Potrzebujemy tych próbek rudy, i to szybko, inaczej nasz eksperyment się nie powiedzie!', '', 0),
(12185, 'koKR', '', 'Sin\'dorei stracili w ostatnich latach o wiele za dużo. Naszą ziemię, nasze domy, nawet naszą tożsamość...$B$BNajwyższy czas, byśmy zaczęli to wszystko odbierać.', 0),
(12187, 'koKR', '', '$N, przejdźmy przez przedsionek po prawej.', 0),
(12188, 'koKR', '', 'Widzę światełko w tunelu!', 0),
(12189, 'koKR', '', 'Tam już widać Enklawę Obieżyświatów, $N. Niedaleko... uwaga! Trolle w zasadzce!!', 0),
(12190, 'koKR', '', 'Kapitanie Heliosie, uratowano mnie z Katakumb Amanów. Melduję się na służbie, panie kapitanie!', 0),
(12191, 'koKR', '', 'Dziękuję, że $gocaliłeś:ocaliłaś; mi życie i $gsprowadziłeś:sprowadziłaś; mnie w bezpieczne miejsce, $N!', 0),
(12193, 'koKR', 'Lilatho, niech ktoś obejrzy te rany. Dziękuję, że bezpiecznie ją $gsprowadziłeś:sprowadziłaś;.', '', 0),
(12196, 'koKR', 'Wśród licznych pergaminów z listami kontrolnymi i innymi notatkami Obieżyświatów jeden przykuwa uwagę. To rysunek ohydnego trolla, być może najstraszliwszego stwora, jakiego kiedykolwiek $gwidziałeś:widziałaś;!', '', 0),
(12208, 'koKR', '', 'Poznanie wroga daje wiele przewag. Weź sobie tę lekcję do serca, $N.$B$BIm więcej wiemy o Pladze, tym lepiej jesteśmy przygotowani, by ją pokonać.', 0),
(12210, 'koKR', '', 'Możesz zostać w Enklawie Obieżyświatów, jak długo zechcesz, $N. Chętnie przyjmujemy każdego, kto zechce wesprzeć nas w naszych staraniach na Widmowych Ziemiach.', 0),
(12211, 'koKR', 'Zabłąkane siły tajemne potrafią dziwnie wpływać na ziemię, żywioły, a nawet na duchy zmarłych.', '', 0),
(12212, 'koKR', 'Najwyższy egzekutor to bardzo zajęty człowiek, $N. Może ja pomogę ci w tym, czego potrzebujesz?', '', 0),
(12220, 'koKR', '', 'Dzięki. Nigdy nie powinnam była opuszczać Srebrzystego Boru.', 0),
(12221, 'koKR', 'Masz moją wdzięczność!', '', 0),
(12222, 'koKR', 'Dzię... dziękuję. Myślałem, że już po mnie.', '', 0),
(12223, 'koKR', 'Zapłacicie śmiercią za to zuchwalstwo!', '', 0),
(12224, 'koKR', 'Śmiertelni głupcy! Ghule Ostoi Śmierci pożywią się waszymi szczątkami!', '', 0),
(12225, 'koKR', 'Wasza śmierć będzie powolna i bolesna!', '', 0),
(12278, 'koKR', 'Sin\'dorei i Porzuconych łączy na Widmowych Ziemiach wspólny cel, $N. Razem pokonamy Plagę, a kto wie... może Porzuceni okażą się cennymi sojusznikami w naszym dążeniu do Rubieży.', '', 0),
(12394, 'koKR', 'Dar\'Khan myśli, że poddamy się Pladze bez walki. Udowodnimy mu, że się myli, $N.', '', 0),
(12423, 'koKR', 'Czasem stoję tutaj, patrzę na las za jeziorem i widzę tę krainę taką, jaka była niegdyś... zieloną i pełną życia.', '', 0),
(12424, 'koKR', 'Naprawdę musimy wymyślić sposób, by poradzić sobie z tymi śmierdzącymi trollami Cienistej Sosny!', '', 0),
(12430, 'koKR', '', 'Musimy zachować czujność, $N! Między Dar\'Khanem Zdrajcą i jego Plagą a trollami Cienistej Sosny, za którymi stoi potęga Zul\'Aman, ledwo utrzymujemy się tu na powierzchni. Naprawdę nie powinniśmy dzielić uwagi!$B$BMam nadzieję, że przybywasz z pomocą.', 0),
(12447, 'koKR', 'Niewielu uczniów spotyka się w tych stronach, prawda? Zaczynam podejrzewać, że to dlatego, że magistrowie zlecają nam całą niebezpieczną robotę, której sami woleliby nie robić.', '', 0),
(12526, 'koKR', 'Im większe uznanie zyskasz w naszym mieście, tym więcej towarów będzie dla ciebie dostępnych, $N. Sprzętu jest tak mało, że możemy go wydawać tylko tym, którym ufamy.', '', 0),
(12527, 'koKR', 'Pokaż mi, do czego mam dostęp, Vredigarze.', 'Pokaż mi, do czego mam dostęp, Vredigarze.', 0),
(12530, 'koKR', 'To nie moja wina... TO NIE MOJA WINA!!!$B$BGdyby tylko zrobili to, co im kazałem, wszystko byłoby dobrze. Ale nie! Nie chcieli słuchać.$B$BA teraz wszyscy nie żyją.$B$BChcę tylko wrócić do domu. Do domu, do Srebrnej Luny. Jestem taki zmęczony.', '', 0),
(12540, 'koKR', 'Powinni byli mnie słuchać. Wtedy zebrałbym wszystkie należne mi pochwały!', '', 0),
(12541, 'koKR', 'Czyż nie krzyczałem do nich? Wycofać się! Wycofać się i przegrupować pod osłoną ognia zaporowego!!', '', 0),
(12542, 'koKR', 'To nie jest Srebrna Luna! Gdzie jesteśmy? Ach, przez chwilę mi się pomyliło.', '', 0),
(12543, 'koKR', 'Mówię ci, tropicielko Valanno, gdy wrócimy do Enklawy Obieżyświatów, rozliczysz się ze wszystkich swoich czynów! To ty sama odpowiadasz za nasze straty i jestem pewien, że kapitan przyzna mi rację.', '', 0),
(12544, 'koKR', 'Masz!', '', 0),
(12545, 'koKR', 'Na pewno po powrocie dostanę pochwałę. Może ponieśliśmy kilka strat, ale ogólnie rzecz biorąc, poszło nam całkiem nieźle, nie sądzisz, Valanno?', '', 0),
(12552, 'koKR', '', 'Egzekutorze, twoje podejście, czyli bezpośredni szturm, będzie nas kosztować więcej istnień, niż jestem gotowa poświęcić. Potrzebna jest subtelniejsza strategia; taka, w której odbijemy okoliczne tereny, zaczynając od wiosek, by odciąć Ostoi Śmierci wszelkie źródła posiłków.', 0),
(12557, 'koKR', '', 'Ile jeszcze do przybycia posiłków Porzuconych? Nasze położenie jest tu niepewne. Wasza Pani obiecała nam więcej żołnierzy. Musimy móc skupić się wyłącznie na Ostoi Śmierci i Pladze!', 0),
(12562, 'koKR', '', 'Nie, od początku miałam rację. Ostoja Śmierci musi być na końcu. Najpierw musimy zabezpieczyć całe Widmowe Ziemie. Nie rzucę tutejszych sił do walki z Dar\'Khanem, mając wrogów na flance i na tyłach!', 0),
(12571, 'koKR', '', 'Słyszę, co mówisz, Mavrenie. Mimo to ostateczna decyzja należy do mnie. Doceniam twoją pomoc, ale większość istnień, o które toczy się gra, to krwawe elfy. Nie pozwolę, by ktoś lekkomyślnie je zmarnował!', 0),
(12572, 'koKR', '', 'Mavrenie, nie chcę wymówek, chcę wyników! Obieżyświaci są niedostępni, a od Srebrnej Luny dostaliśmy na razie wszystko, co mogliśmy dostać. Nie mogę zignorować trolli Cienistej Sosny i Zul\'Aman... stoją wzdłuż całej naszej wschodniej granicy!', 0),
(12573, 'koKR', '', 'Możesz się ze mną nie zgadzać, ile chcesz, najwyższy egzekutorze. Rozważę twoją radę, a potem podejmiemy kroki, które uznam za konieczne, by wyzwolić całe Quel\'Thalas. Wrócimy do tej rozmowy później.', 0),
(12574, 'koKR', '', '%s wygląda na zbulwersowaną tonem egzekutora!', 0),
(12575, 'koKR', '', '%s próbuje zająć się czymś innym.', 0),
(12576, 'koKR', '', '%s rzuca mordercze spojrzenia w stronę najwyższego egzekutora Mavrena i tropiciela śmierci Maltendisa.', 0),
(12577, 'koKR', '', '%s zadziera nos i prycha w odpowiedzi na słowa najwyższego egzekutora.', 0),
(12578, 'koKR', '', '%s z niedowierzaniem kręci głową, słysząc, co wychodzi z ust Porzuconego.', 0),
(12579, 'koKR', '', '%s blednie, a krew niemal całkiem odpływa jej z twarzy.', 0),
(12580, 'koKR', '', '%s czerwienieje z wściekłości, słysząc odpowiedź na pytanie swojej pani.', 0),
(12581, 'koKR', '', '%s wpatruje się w przeciwległą ścianę, ostentacyjnie ignorując spojrzenia egzekutora i jego pomocnika.', 0),
(12582, 'koKR', '%s kiwa głową na znak zgody.', '', 0),
(12583, 'koKR', '%s otwiera usta, jakby chciał coś dodać, ale najwyraźniej się rozmyśla.', '', 0),
(12584, 'koKR', '%s zerka na doradczynię Valwyn z drwiącym uśmieszkiem.', '', 0),
(12585, 'koKR', '%s uśmiecha się szeroko, słysząc słowa najwyższego egzekutora.', '', 0),
(12586, 'koKR', '%s wygląda na znudzonego całą tą dyskusją.', '', 0),
(12587, 'koKR', '%s chytrze puszcza oko do doradczyni Valwyn.', '', 0),
(12588, 'koKR', '%s nerwowo poprawia zbroję, wyraźnie skrępowany tonem dyskusji.', '', 0),
(12589, 'koKR', '%s wygląda, jakby wolał być gdziekolwiek, byle nie tutaj.', '', 0),
(12590, 'koKR', '%s niecierpliwie przytupuje.', '', 0),
(12591, 'koKR', '%s piorunuje wzrokiem strażników.', '', 0),
(12592, 'koKR', '%s wzdycha z wyraźną frustracją.', '', 0),
(12593, 'koKR', '%s zagląda do wieży i zaciska szczęki.', '', 0),
(12594, 'koKR', 'Czemu Kaendris wciąż nie rusza na Dar\'Khana? Na co czekamy?', '', 0),
(12595, 'koKR', '', 'Uspokój się, Idonisie. Pochopne działania do niczego nas nie doprowadzą! Zrób sobie przerwę, zaczerpnij trochę mocy z kryształów many. Poczujesz się lepiej.', 0),
(12596, 'koKR', '', 'Ma swoje powody, Idonisie. Sądzi, że Obieżyświaci coś odkryli.', 0),
(12597, 'koKR', '', 'Musimy skupić się na pracy. Gdy sanktuarium zacznie działać pełną mocą, Srebrna Luna będzie musiała przysłać pomoc. Działających tajemnych sanktuariów jest jak na lekarstwo.', 0),
(12616, 'koKR', '', 'Witaj, $N. Jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, koniecznie porozmawiaj z Obieżyświatką Solanną.', 0),
(13361, 'koKR', '', '%s szepcze coś damie do ucha.', 0),
(13362, 'koKR', '', '%s kiwa głową, przytakując temu, co mówi jej doradczyni.', 0),
(13363, 'koKR', '', '%s nie zgadza się z tym, co wyszeptała jej Valwyn.', 0),
(13365, 'koKR', '', '%s wydaje się zbita z tropu tym, co wyszeptała jej do ucha doradczyni.', 0),
(13366, 'koKR', '%s odwraca się do doradczyni Valwyn i lubieżnie puszcza do niej oko.', '', 0),
(13367, 'koKR', '', '%s patrzy z obrzydzeniem na zaloty tropiciela śmierci.', 0),
(13368, 'koKR', '%s rechocze jak szaleniec, łącząc dwie mikstury, które trzyma w dłoniach.', '', 0),
(13369, 'koKR', 'Psiakrew! Ten wyciąg z krwawego ostu jakoś nie chce się porządnie połączyć z moją trucizną. Nie dam się zniechęcić – z tymi trollami trzeba się rozprawić! Może inna mieszanka?', '', 0),
(14250, 'koKR', 'Mistrzu kuchni, czy możesz nauczyć mnie sztuki kulinarnej?', 'Mistrzu kuchni, czy możesz nauczyć mnie sztuki kulinarnej?', 0),
(14252, 'koKR', 'Masz jakieś zapasy kucharskie?', 'Masz jakieś zapasy kucharskie?', 0),
(14255, 'koKR', '', 'Po zaopatrzenie kowalskie $gprzyszedłeś:przyszłaś;, co?', 0),
(14256, 'koKR', 'Mam świeże mięso, ryby i grzyby. I mnóstwo do picia!', '', 0),
(14266, 'koKR', 'Mam się zająć twoimi zwierzęcymi towarzyszami?', '', 0),
(14267, 'koKR', 'Chcę skorzystać ze stajni.', 'Chcę skorzystać ze stajni.', 0),
(14407, 'koKR', 'Oglądając zwłoki, dochodzisz do wniosku, że to musi być Krwawy Rycerz Gwiazda Zaranna, dowódca nieudanego szturmu na Ostoję Śmierci.', '', 0),
(16317, 'koKR', 'Ja... rzucę okiem.', 'Ja... rzucę okiem.', 0),
(16318, 'koKR', 'Ej! Ej, $N! Mam coś w sam raz dla ciebie. $GWidziałeś:Widziałaś; kiedy tikbalanga? Straszne stwory. Lubią porywać ludzi. Tobie trza jednej z moich ochron przed tikbalangami. Gwarantowane, że odstraszy wszystkie tikbalangi!', '', 0),
(16319, 'koKR', 'Chodź no tu, $N! Mam coś dla ciebie. Akurat to, czego ci trza. To mydło, no... i to na sznurku! Bez urazy, $gchłopie:kochana;, ale trochę od ciebie zalatuje, wiesz, o co mi chodzi?', '', 0),
(16320, 'koKR', 'Wyglądasz na $gchorego:chorą; z miłości. Ktoś wyjątkowy cię dołuje, co? Spokojna głowa, spokojna głowa. Weźmiesz ode mnie ten medalion, założysz go, jak tę osobę zobaczysz, i będzie się do ciebie kleić, $gchłopie:złotko;!', '', 0),
(16321, 'koKR', 'Niebezpiecznie tam, co nie? Wiesz, czego ci trza? Ochrony. Pomogę ci oszukać samą śmierć! Nosisz ten szalokamień na szyi, widzisz, i jak trafisz do świata duchów, to możesz wrócić! Tylko szybki spacerek do twoich zwłok i hop, wstajesz $gjak nowo narodzony:jak nowo narodzona;!', '', 0),
(16322, 'koKR', 'Zdumiewające amulety! Niesamowite osobliwości! Ci nowomodni jubilerzy nie mają startu do sprawdzonych mistycznych metod starego Griftaha! Stań się kimś lepszym dzięki tym magicznym talizmanom za okazyjną cenę!', '', 0),
(16323, 'koKR', 'Chodź no tu, $N. Chyba nie chcesz się narażać w jakimś lochu, co? Brudna robota, a po co? Dla jakiejś bezwartościowej błyskotki? Nie, tobie trza jednego z moich amuletów. Gwarantowane, że działa!', '', 0),
(16324, 'koKR', 'Wyglądasz na $gzmęczonego:zmęczoną;, $N. Mam coś dla ciebie. Te amulety pomogą ci przeskakiwać przeszkody i pływać w rzekach jak ryba w wodzie. Dodają mocy jedzeniu, co je jesz, i rany zamykają się w oczach!', '', 0),
(19887, 'koKR', 'Wyśmienicie! Świeże części!', '', 0),
(19888, 'koKR', 'Jakże to miło z twojej strony, że oddajesz swoje narządy!', '', 0),
(19889, 'koKR', 'Możesz być $gdumny:dumna; – twój mózg zostanie dobrze wykorzystany w jednym z moich plugastw.', '', 0),
(22152, 'koKR', 'Mogę jedynie założyć, że wiesz, kim jestem. A mimo to upierasz się, by mi przeszkadzać?$b$bCóż takiego możesz chcieć, że wymaga to mojej uwagi?', '', 0),
(22204, 'koKR', 'No, witaaam, ślicznotko...', '', 0),
(22205, 'koKR', 'Widzę, że dziś zgrywamy niedostępną.... No dobrze, może później zastanę cię w lepszym nastroju.', '', 0),
(22206, 'koKR', 'Hmm, nie odmówię!', '', 0),
(22207, 'koKR', '', 'Nie teraz, Mack. Nie mam ochoty na twoje pijackie obmacywanie. Spadaj!', 0),
(22209, 'koKR', 'Jak sobie życzysz, księżniczko. Ale tylko odwlekasz nieuniknione....', '', 0),
(22210, 'koKR', 'No i czemu chcesz złamać biednemu Mackowi serce? Jak wrócę, będę się modlił, żebyś zmieniła zdanie....', '', 0),
(22211, 'koKR', 'Miękniesz, księżniczko. Czuję to!', '', 0),
(22212, 'koKR', '', 'Zjeżdżaj, Mack! Bo każę Buddowi ugotować cię dla moich psów....', 0),
(22213, 'koKR', '', 'Nie ma tu nic do picia, Mack. Precz!', 0),
(22214, 'koKR', '', 'Idź się wykąp w jeziorze, co, Mack? Poczułam cię, zanim cię zobaczyłam....', 0),
(22215, 'koKR', 'No proszę, cóż to za zjawisko pełne wdzięku?', '', 0),
(22216, 'koKR', 'Ach, moja najdroższa Ameenah! Jak cudownie znów cię widzieć.', '', 0),
(22217, 'koKR', 'Hmpf. I tak nigdy jej nie lubiłem....', '', 0),
(22218, 'koKR', 'Mmm, nic, czego odrobina smarowania nie naprawi!', '', 0),
(22219, 'koKR', 'Nigdy nie pij przed piątą, mawiała mamusia. No cóż, mamusiu, gdzieś na świecie na pewno już jest piąta!', '', 0),
(22220, 'koKR', '<kaszel> Ugh...', '', 0),
(22221, 'koKR', 'Juhuuu! Jak mawiał tatuś, robię miejsce na więcej! He, he.', '', 0),
(22222, 'koKR', 'Ooo. Coś mi dziś brzuszek nie służy...', '', 0),
(22223, 'koKR', 'Hmmm, może dam tym starym kościom chwilę odpocząć.', '', 0),
(22224, 'koKR', 'Załoga Budda, znaczy?$b$bAno, on nie przebiera w ludziach. Weźmie każdego, kto umie machać łopatą$b$b...oprócz nieumarłych. Budd ich nienawidzi. Jak dla mnie, to on się ich boi.', '', 0),
(22225, 'koKR', 'Kim jest ten cały Budd?', 'Kim jest ten cały Budd?', 0),
(22226, 'koKR', 'Co taki gość jak ja może zrobić dla kogoś takiego jak ty w takiej chwili?', '', 0),
(22227, 'koKR', 'Mogę coś dla ciebie zrobić, $N?', '', 0),
(22228, 'koKR', 'Jak $gprzyszedłeś:przyszłaś; po udział w wielkim łupie, to ustaw się w kolejce!$b$bMój udział już dawno mi się należy....', '', 0),
(22229, 'koKR', 'A skąd mam wiedzieć, dzieciaku? Jestem w załodze od niedawna.$b$bZabijania trolli i picia grogu mam już po dziurki w nosie, tyle ci powiem. Zostało mi tylko zobaczyć skarb, który Budd ciągle obiecuje....', '', 0),
(22230, 'koKR', 'Ciekawą masz tu załogę....', 'Ciekawą masz tu załogę....', 0),
(22232, 'koKR', 'Aj, nigdy nie wiadomo, kto dołączy następny, a kto następny wyzionie ducha, jeśli już o tym mowa.$b$bMoja rada? Nie przywiązuj się do nikogo.', '', 0),
(22233, 'koKR', 'Zgadza się. Budd pozbierał hołotę z całego świata.$b$bJak widać, gdy jest darmowa gorzała, znajdzie się mnóstwo ludzi gotowych zapomnieć o dzielących ich różnicach.', '', 0),
(22234, 'koKR', 'Uff! Co tu tak śmierdzi?', 'Uff! Co tu tak śmierdzi?', 0),
(22235, 'koKR', '<obwąchuje się i krzywi>$b$bTo, $N, jest zapach przygody!', '', 0),
(22236, 'koKR', '<hik> Słuchaj no, $N. Spędź dzień czy dwa na mocowaniu się z dzikimi trollami, a potem mi powiedz, jak ty pachniesz!', '', 0),
(22237, 'koKR', 'Aaa, to. Widzisz, ostatnio w obozie nie ma nic prócz orczego grogu.$b$bA orczy grog jakoś mi nie służy, jeśli wiesz, co mam na myśli....', '', 0),
(22238, 'koKR', '', 'Aha. Jak sobie chcesz.', 0),
(22239, 'koKR', '', 'Idiota.', 0),
(22240, 'koKR', '', 'Czy mógłbyś się łaskawie zamknąć?!', 0),
(22241, 'koKR', '', 'Przypomnij mi jeszcze raz, dlaczego po prostu stąd nie odejdę?', 0),
(22242, 'koKR', '', 'Jesteś najbardziej niekompetentnym oficerem, jakiego w życiu spotkałam!', 0),
(22243, 'koKR', '', 'Z całym szacunkiem, panie poruczniku, wsadź to sobie!', 0),
(22252, 'koKR', '', 'Turgore! Wstawaj i pomóż mi rozładować, ty leniwy peonie!', 0),
(22253, 'koKR', '', 'Bezużyteczny ork! Poczekaj tylko, któregoś dnia wrzucę ci coś do grogu i już się NIGDY nie obudzisz....', 0),
(22254, 'koKR', '', 'Powiedz no, Brend, czemu nigdy nie robisz do mnie maślanych oczu?', 0),
(22255, 'koKR', 'Cóż, Marge, prawdę mówiąc, od dawna szukam sposobu, żeby ci to powiedzieć....', '', 0),
(22256, 'koKR', 'Ile bym nie wypił, i tak nie robisz się ładniejsza!', '', 0),
(22258, 'koKR', '', 'Ooooch. Jak śmiesz!', 0),
(22259, 'koKR', '', 'Niech to będzie dla ciebie nauczka....', 0),
(22265, 'koKR', '', 'Powiedz no, Brend, szepnij mi coś miłego, co?', 0),
(22266, 'koKR', '', 'Ale Brend, ty ciągle pijesz!', 0),
(22267, 'koKR', '', 'Plugawy ork!', 0),
(22268, 'koKR', 'Słuchaj, Marge, chyba ci mówiłem, żebyś nigdy mi nie przeszkadzała, kiedy piję....', '', 0),
(22269, 'koKR', 'Ej, Morgom, zdaje się, że Marge potrzebuje trochę uwagi. Co ty na to?', '', 0),
(22270, 'koKR', 'Zug Zug!', '', 0),
(22369, 'koKR', 'Słuchaj, $N, widać, że ty i twoi przyjaciele znacie Azeroth jak własną kieszeń. Z pewnością spotkaliście ludzi łaknących sławy i bogactwa.$b$bPrzyślij do mnie każdego, kto zechce wejść do Zul\'Aman, a sowicie ci to wynagrodzę.', '', 0),
(22383, 'koKR', 'To ty zaopatrzyłeś załogę w przebrania?', 'To ty zaopatrzyłeś załogę w przebrania?', 0),
(23251, 'koKR', 'Hahaha, widzisz to? Griftah WRÓCIŁ! Z powrotem w swoim straganie, z powrotem ze starym towarem i gotów robić z tobą interesy!$b$bChcesz być $glepszy, silniejszy, szybszy:lepsza, silniejsza, szybsza;? Każdy z tych amuletów gwarantuje, że robi dokładnie to, co mówię. Podejdź i kup jedną z tych cudownych błyskotek! Tanie nawet za podwójną cenę!', '', 0),
(23591, 'koKR', 'Cień na ciebie padnie....', '', 0),
(23593, 'koKR', 'To koszmar, z którego się nie obudzisz!', '', 0),
(23594, 'koKR', 'Azzaga choogo zinn!', '', 0),
(23596, 'koKR', 'Ciemność po ciebie idzie....', '', 0),
(23597, 'koKR', 'Twoja dusza będzie krwawić!', '', 0),
(23601, 'koKR', 'To nie... koniec dla mnie!', '', 0);
